1	// ── 청크/resumable 업로드 세션(디스크 기반) — PLAN-remaining-backlog-design §8 ──────────────────────
2	// GB급·불안정망 대비: 클라가 큰 파일을 고정 크기 청크로 쪼개 ★offset 순서대로★ 전송, 서버는 임시 .part 파일에
3	//   append 하며 누적 바이트를 메타에 기록한다. 끊기면 클라가 status로 received를 물어 ★실패 지점부터 재개★.
4	//   순수 판정(planChunks/classifyChunkOffset/isUploadComplete)은 lib/uploadChunks(테스트됨)를 재사용.
5	// ★멀티팟 주의★: 세션은 OS 임시폴더(파드 로컬)에 둔다 → 같은 업로드의 모든 청크가 같은 파드로 가야 한다
6	//   (프로드 다중 파드는 sticky session 또는 공유 볼륨 필요). 파일럿/로컬·단일 파드에선 그대로 동작. (§8 후속)
7	import { promises as fs } from "node:fs";
8	import os from "node:os";
9	import path from "node:path";
10	import crypto from "node:crypto";
11	import { classifyChunkOffset, isUploadComplete } from "@/lib/uploadChunks";
12	
13	export const CHUNK_BYTES = 8 * 1024 * 1024; // 권장 청크 크기(클라가 이 크기로 분할) — 8MB
14	const SESSION_TTL_MS = 6 * 60 * 60 * 1000; // 미완료 세션 보관 6시간(이후 청소 대상)
15	
16	function baseDir(): string {
17	  return process.env.CHUNK_UPLOAD_DIR?.trim() || path.join(os.tmpdir(), "llmwiki-chunked");
18	}
19	// uploadId는 우리가 발급한 hex만 허용(경로 탈출·임의 파일 접근 차단).
20	function safeId(uploadId: string): string {
21	  if (!/^[a-f0-9]{32}$/.test(uploadId)) throw new Error("잘못된 uploadId");
22	  return uploadId;
23	}
24	function metaPath(id: string): string { return path.join(baseDir(), `${id}.json`); }
25	function partPath(id: string): string { return path.join(baseDir(), `${id}.part`); }
26	
27	export interface ChunkSessionMeta {
28	  uploadId: string;
29	  userId: number;
30	  scope: string;
31	  filename: string;
32	  mime: string;
33	  title: string;
34	  anonymous: boolean;
35	  geminiOptIn: boolean;
36	  size: number;     // 클라가 알린 총 바이트
37	  received: number; // 누적 수신 바이트
38	  createdAt: number;
39	}
40	
41	/** 오래된 미완료 세션 청소(best-effort) — 디스크 누수 방지. 호출 실패는 무시. */
42	async function pruneStale(): Promise<void> {
43	  try {
44	    const dir = baseDir();
45	    const names = await fs.readdir(dir).catch(() => [] as string[]);
46	    const now = Date.now();
47	    for (const n of names) {
48	      if (!n.endsWith(".json")) continue;
49	      try {
50	        const m = JSON.parse(await fs.readFile(path.join(dir, n), "utf8")) as ChunkSessionMeta;
51	        if (now - (m.createdAt || 0) > SESSION_TTL_MS) {
52	          await fs.unlink(metaPath(m.uploadId)).catch(() => {});
53	          await fs.unlink(partPath(m.uploadId)).catch(() => {});
54	        }
55	      } catch { /* 손상 메타 무시 */ }
56	    }
57	  } catch { /* noop */ }
58	}
59	
60	/** 업로드 세션 생성 — 빈 .part + 메타 기록. uploadId 반환. */
61	export async function createChunkSession(input: Omit<ChunkSessionMeta, "uploadId" | "received" | "createdAt">): Promise<ChunkSessionMeta> {
62	  await fs.mkdir(baseDir(), { recursive: true });
63	  void pruneStale();
64	  const uploadId = crypto.randomBytes(16).toString("hex");
65	  const meta: ChunkSessionMeta = { ...input, uploadId, received: 0, createdAt: Date.now() };
66	  await fs.writeFile(partPath(uploadId), Buffer.alloc(0)); // 빈 파일 생성
67	  await fs.writeFile(metaPath(uploadId), JSON.stringify(meta), "utf8");
68	  return meta;
69	}
70	
71	/** 세션 메타 조회(없으면 null). */
72	export async function getChunkSession(uploadId: string): Promise<ChunkSessionMeta | null> {
73	  try {
74	    return JSON.parse(await fs.readFile(metaPath(safeId(uploadId)), "utf8")) as ChunkSessionMeta;
75	  } catch {
76	    return null;
77	  }
78	}
79	
80	export class ChunkGapError extends Error {
81	  constructor(public expected: number, public got: number) { super(`청크 offset 불연속(기대 ${expected}, 받음 ${got})`); }
82	}
83	
84	/**
85	 * 청크 1개 append — offset이 현재 received와 맞아야 한다(순수 classifyChunkOffset로 판정).
86	 * - ok: 이어붙이고 received 증가. duplicate(이미 받은 구간 재전송): 무시하고 현재 received 반환(idempotent).
87	 * - gap(건너뜀): ChunkGapError(클라가 status로 received를 받아 재개).
88	 */
89	export async function appendChunk(uploadId: string, offset: number, chunk: Buffer): Promise<{ received: number; complete: boolean }> {
90	  const id = safeId(uploadId);
91	  const meta = await getChunkSession(id);
92	  if (!meta) throw new Error("업로드 세션을 찾을 수 없습니다(만료되었거나 다른 서버일 수 있어요).");
93	  const cls = classifyChunkOffset(meta.received, offset);
94	  if (cls === "duplicate") return { received: meta.received, complete: isUploadComplete(meta.received, meta.size) };
95	  if (cls === "gap") throw new ChunkGapError(meta.received, offset);
96	  if (meta.received + chunk.byteLength > meta.size) throw new Error("총 크기를 초과하는 청크입니다.");
97	  // append(순차 전송 가정 — 단일 클라가 offset 순으로 보냄). O_APPEND로 원자적 추가.
98	  await fs.appendFile(partPath(id), chunk);
99	  meta.received += chunk.byteLength;
100	  await fs.writeFile(metaPath(id), JSON.stringify(meta), "utf8");
101	  return { received: meta.received, complete: isUploadComplete(meta.received, meta.size) };
102	}
103	
104	/** 완료된 세션의 임시 파일 경로(파이널라이즈용). 미완료면 throw. */
105	export async function chunkSessionTempPath(uploadId: string): Promise<{ tempPath: string; meta: ChunkSessionMeta }> {
106	  const id = safeId(uploadId);
107	  const meta = await getChunkSession(id);
108	  if (!meta) throw new Error("업로드 세션을 찾을 수 없습니다.");
109	  if (!isUploadComplete(meta.received, meta.size)) throw new Error(`업로드가 아직 끝나지 않았습니다(${meta.received}/${meta.size}).`);
110	  return { tempPath: partPath(id), meta };
111	}
112	
113	/** 세션 정리(메타 + .part 삭제). 파이널라이즈 성공/취소 후 호출. */
114	export async function cleanupChunkSession(uploadId: string): Promise<void> {
115	  try {
116	    const id = safeId(uploadId);
117	    await fs.unlink(metaPath(id)).catch(() => {});
118	    await fs.unlink(partPath(id)).catch(() => {});
119	  } catch { /* noop */ }
120	}
