// ── 청크/resumable 업로드 세션(디스크 기반) — PLAN-remaining-backlog-design §8 ──────────────────────
// GB급·불안정망 대비: 클라가 큰 파일을 고정 크기 청크로 쪼개 ★offset 순서대로★ 전송, 서버는 임시 .part 파일에
//   append 하며 누적 바이트를 메타에 기록한다. 끊기면 클라가 status로 received를 물어 ★실패 지점부터 재개★.
//   순수 판정(planChunks/classifyChunkOffset/isUploadComplete)은 lib/uploadChunks(테스트됨)를 재사용.
// ★멀티팟 주의★: 세션은 OS 임시폴더(파드 로컬)에 둔다 → 같은 업로드의 모든 청크가 같은 파드로 가야 한다
//   (프로드 다중 파드는 sticky session 또는 공유 볼륨 필요). 파일럿/로컬·단일 파드에선 그대로 동작. (§8 후속)
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";
import { classifyChunkOffset, isUploadComplete } from "@/lib/uploadChunks";

export const CHUNK_BYTES = 8 * 1024 * 1024; // 권장 청크 크기(클라가 이 크기로 분할) — 8MB
const SESSION_TTL_MS = 6 * 60 * 60 * 1000; // 미완료 세션 보관 6시간(이후 청소 대상)

function baseDir(): string {
  return process.env.CHUNK_UPLOAD_DIR?.trim() || path.join(os.tmpdir(), "llmwiki-chunked");
}
// uploadId는 우리가 발급한 hex만 허용(경로 탈출·임의 파일 접근 차단).
function safeId(uploadId: string): string {
  if (!/^[a-f0-9]{32}$/.test(uploadId)) throw new Error("잘못된 uploadId");
  return uploadId;
}
function metaPath(id: string): string { return path.join(baseDir(), `${id}.json`); }
function partPath(id: string): string { return path.join(baseDir(), `${id}.part`); }

export interface ChunkSessionMeta {
  uploadId: string;
  userId: number;
  scope: string;
  filename: string;
  mime: string;
  title: string;
  anonymous: boolean;
  geminiOptIn: boolean;
  size: number;     // 클라가 알린 총 바이트
  received: number; // 누적 수신 바이트
  createdAt: number;
}

/** 오래된 미완료 세션 청소(best-effort) — 디스크 누수 방지. 호출 실패는 무시. */
async function pruneStale(): Promise<void> {
  try {
    const dir = baseDir();
    const names = await fs.readdir(dir).catch(() => [] as string[]);
    const now = Date.now();
    for (const n of names) {
      if (!n.endsWith(".json")) continue;
      try {
        const m = JSON.parse(await fs.readFile(path.join(dir, n), "utf8")) as ChunkSessionMeta;
        if (now - (m.createdAt || 0) > SESSION_TTL_MS) {
          await fs.unlink(metaPath(m.uploadId)).catch(() => {});
          await fs.unlink(partPath(m.uploadId)).catch(() => {});
        }
      } catch { /* 손상 메타 무시 */ }
    }
  } catch { /* noop */ }
}

/** 업로드 세션 생성 — 빈 .part + 메타 기록. uploadId 반환. */
export async function createChunkSession(input: Omit<ChunkSessionMeta, "uploadId" | "received" | "createdAt">): Promise<ChunkSessionMeta> {
  await fs.mkdir(baseDir(), { recursive: true });
  void pruneStale();
  const uploadId = crypto.randomBytes(16).toString("hex");
  const meta: ChunkSessionMeta = { ...input, uploadId, received: 0, createdAt: Date.now() };
  await fs.writeFile(partPath(uploadId), Buffer.alloc(0)); // 빈 파일 생성
  await fs.writeFile(metaPath(uploadId), JSON.stringify(meta), "utf8");
  return meta;
}

/** 세션 메타 조회(없으면 null). */
export async function getChunkSession(uploadId: string): Promise<ChunkSessionMeta | null> {
  try {
    return JSON.parse(await fs.readFile(metaPath(safeId(uploadId)), "utf8")) as ChunkSessionMeta;
  } catch {
    return null;
  }
}

export class ChunkGapError extends Error {
  constructor(public expected: number, public got: number) { super(`청크 offset 불연속(기대 ${expected}, 받음 ${got})`); }
}

/**
 * 청크 1개 append — offset이 현재 received와 맞아야 한다(순수 classifyChunkOffset로 판정).
 * - ok: 이어붙이고 received 증가. duplicate(이미 받은 구간 재전송): 무시하고 현재 received 반환(idempotent).
 * - gap(건너뜀): ChunkGapError(클라가 status로 received를 받아 재개).
 */
export async function appendChunk(uploadId: string, offset: number, chunk: Buffer): Promise<{ received: number; complete: boolean }> {
  const id = safeId(uploadId);
  const meta = await getChunkSession(id);
  if (!meta) throw new Error("업로드 세션을 찾을 수 없습니다(만료되었거나 다른 서버일 수 있어요).");
  const cls = classifyChunkOffset(meta.received, offset);
  if (cls === "duplicate") return { received: meta.received, complete: isUploadComplete(meta.received, meta.size) };
  if (cls === "gap") throw new ChunkGapError(meta.received, offset);
  if (meta.received + chunk.byteLength > meta.size) throw new Error("총 크기를 초과하는 청크입니다.");
  // append(순차 전송 가정 — 단일 클라가 offset 순으로 보냄). O_APPEND로 원자적 추가.
  await fs.appendFile(partPath(id), chunk);
  meta.received += chunk.byteLength;
  await fs.writeFile(metaPath(id), JSON.stringify(meta), "utf8");
  return { received: meta.received, complete: isUploadComplete(meta.received, meta.size) };
}

/** 완료된 세션의 임시 파일 경로(파이널라이즈용). 미완료면 throw. */
export async function chunkSessionTempPath(uploadId: string): Promise<{ tempPath: string; meta: ChunkSessionMeta }> {
  const id = safeId(uploadId);
  const meta = await getChunkSession(id);
  if (!meta) throw new Error("업로드 세션을 찾을 수 없습니다.");
  if (!isUploadComplete(meta.received, meta.size)) throw new Error(`업로드가 아직 끝나지 않았습니다(${meta.received}/${meta.size}).`);
  return { tempPath: partPath(id), meta };
}

/** 세션 정리(메타 + .part 삭제). 파이널라이즈 성공/취소 후 호출. */
export async function cleanupChunkSession(uploadId: string): Promise<void> {
  try {
    const id = safeId(uploadId);
    await fs.unlink(metaPath(id)).catch(() => {});
    await fs.unlink(partPath(id)).catch(() => {});
  } catch { /* noop */ }
}

