1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { assertScopeAllowed } from "@/lib/acl/scope";
4	import { readFile } from "node:fs/promises";
5	import { stageBuffer, capBytesFor, isAudioVideoExt } from "@/lib/materials/stage";
6	import {
7	  CHUNK_BYTES, createChunkSession, getChunkSession, appendChunk, ChunkGapError,
8	  chunkSessionTempPath, cleanupChunkSession,
9	} from "@/lib/materials/chunkSession";
10	
11	// ── 청크/resumable 업로드 엔드포인트(PLAN-remaining-backlog-design §8) ──────────────────────
12	//   POST {action:"create"}  → 세션 생성(uploadId·chunkSize)
13	//   PATCH ?uploadId=&offset= (octet-stream 청크) → append(received·complete)
14	//   POST {action:"finalize", uploadId} → 임시파일을 stageBuffer로 ★기존 업로드와 동일하게 스테이징★
15	//   GET ?uploadId= → 진행 상태(received·size) — 끊긴 뒤 재개 지점 확인
16	// 큰 파일(>25MB)에서 ★실패 청크만 재시도★해 GB급·불안정망을 수용. 게이팅·추출·보관은 stageBuffer 단일 진실.
17	export const runtime = "nodejs";
18	export const maxDuration = 600;
19	
20	function extOf(filename: string): string {
21	  return (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
22	}
23	
24	export async function POST(req: Request) {
25	  const user = await getSessionUser();
26	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
27	  const body = await req.json().catch(() => ({} as Record<string, unknown>));
28	  const action = String(body.action || "");
29	
30	  if (action === "create") {
31	    const scope = String(body.scope || "");
32	    const filename = String(body.filename || "upload.bin");
33	    const size = Number(body.size || 0);
34	    const mime = String(body.mime || "");
35	    if (!Number.isInteger(size) || size <= 0) return NextResponse.json({ error: "유효한 파일 크기(size)가 필요합니다." }, { status: 400 });
36	    try {
37	      await assertScopeAllowed(user, scope); // ACL 강제지점3 — 업로드 시작 전 거부(큰 전송 차단)
38	    } catch {
39	      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
40	    }
41	    // 빠른 실패용 용량 precheck(최종 형식·모델 게이팅은 finalize의 stageBuffer에서). 음성·영상 100MB / 그 외 500MB.
42	    const ext = extOf(filename);
43	    const cap = capBytesFor(ext, mime);
44	    if (size > cap) {
45	      const isAV = isAudioVideoExt(ext, mime);
46	      return NextResponse.json({ error: `파일은 ${Math.round(cap / 1024 / 1024)}MB 이하만 가능합니다.${isAV ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 413 });
47	    }
48	    const meta = await createChunkSession({
49	      userId: user.id, scope, filename, mime,
50	      title: String(body.title || ""), anonymous: Boolean(body.anonymous), geminiOptIn: Boolean(body.geminiOptIn), size,
51	    });
52	    return NextResponse.json({ uploadId: meta.uploadId, chunkSize: CHUNK_BYTES, received: 0 });
53	  }
54	
55	  if (action === "finalize") {
56	    const uploadId = String(body.uploadId || "");
57	    const meta = await getChunkSession(uploadId).catch(() => null);
58	    if (!meta) return NextResponse.json({ error: "업로드 세션을 찾을 수 없습니다." }, { status: 404 });
59	    if (meta.userId !== user.id) return NextResponse.json({ error: "이 업로드의 소유자가 아닙니다." }, { status: 403 });
60	    try {
61	      const { tempPath } = await chunkSessionTempPath(uploadId);
62	      const buf = await readFile(tempPath); // 1회 적재(추출·보관용) — 4Gi limit 내(§11.1)
63	      const res = await stageBuffer(user, buf, meta.filename, meta.mime, {
64	        scope: meta.scope, title: meta.title, anonymous: meta.anonymous, diarize: false, geminiOptIn: meta.geminiOptIn, modelField: "",
65	      });
66	      return res;
67	    } catch (err) {
68	      return NextResponse.json({ error: String(err) }, { status: 400 });
69	    } finally {
70	      await cleanupChunkSession(uploadId);
71	    }
72	  }
73	
74	  return NextResponse.json({ error: "알 수 없는 action입니다(create|finalize)." }, { status: 400 });
75	}
76	
77	// 청크 append — octet-stream 본문, offset은 쿼리스트링. received/complete 반환. gap이면 409 + 현재 received.
78	export async function PATCH(req: Request) {
79	  const user = await getSessionUser();
80	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
81	  const u = new URL(req.url);
82	  const uploadId = u.searchParams.get("uploadId") || "";
83	  const offset = Number(u.searchParams.get("offset"));
84	  if (!Number.isInteger(offset) || offset < 0) return NextResponse.json({ error: "유효한 offset이 필요합니다." }, { status: 400 });
85	  const meta = await getChunkSession(uploadId).catch(() => null);
86	  if (!meta) return NextResponse.json({ error: "업로드 세션을 찾을 수 없습니다(만료되었거나 다른 서버일 수 있어요)." }, { status: 404 });
87	  if (meta.userId !== user.id) return NextResponse.json({ error: "이 업로드의 소유자가 아닙니다." }, { status: 403 });
88	  if (!req.body) return NextResponse.json({ error: "청크 본문이 비었습니다." }, { status: 400 });
89	  const chunk = Buffer.from(await req.arrayBuffer());
90	  try {
91	    const { received, complete } = await appendChunk(uploadId, offset, chunk);
92	    return NextResponse.json({ received, complete });
93	  } catch (err) {
94	    if (err instanceof ChunkGapError) {
95	      // 클라가 received부터 다시 보내도록 — 재개 지점 동봉(409 Conflict).
96	      return NextResponse.json({ error: err.message, received: err.expected }, { status: 409 });
97	    }
98	    return NextResponse.json({ error: String(err) }, { status: 500 });
99	  }
100	}
101	
102	// 진행 상태(재개 지점 확인). 소유자만.
103	export async function GET(req: Request) {
104	  const user = await getSessionUser();
