import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed } from "@/lib/acl/scope";
import { readFile } from "node:fs/promises";
import { stageBuffer, capBytesFor, isAudioVideoExt } from "@/lib/materials/stage";
import {
  CHUNK_BYTES, createChunkSession, getChunkSession, appendChunk, ChunkGapError,
  chunkSessionTempPath, cleanupChunkSession,
} from "@/lib/materials/chunkSession";

// ── 청크/resumable 업로드 엔드포인트(PLAN-remaining-backlog-design §8) ──────────────────────
//   POST {action:"create"}  → 세션 생성(uploadId·chunkSize)
//   PATCH ?uploadId=&offset= (octet-stream 청크) → append(received·complete)
//   POST {action:"finalize", uploadId} → 임시파일을 stageBuffer로 ★기존 업로드와 동일하게 스테이징★
//   GET ?uploadId= → 진행 상태(received·size) — 끊긴 뒤 재개 지점 확인
// 큰 파일(>25MB)에서 ★실패 청크만 재시도★해 GB급·불안정망을 수용. 게이팅·추출·보관은 stageBuffer 단일 진실.
export const runtime = "nodejs";
export const maxDuration = 600;

function extOf(filename: string): string {
  return (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
}

export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const body = await req.json().catch(() => ({} as Record<string, unknown>));
  const action = String(body.action || "");

  if (action === "create") {
    const scope = String(body.scope || "");
    const filename = String(body.filename || "upload.bin");
    const size = Number(body.size || 0);
    const mime = String(body.mime || "");
    if (!Number.isInteger(size) || size <= 0) return NextResponse.json({ error: "유효한 파일 크기(size)가 필요합니다." }, { status: 400 });
    try {
      await assertScopeAllowed(user, scope); // ACL 강제지점3 — 업로드 시작 전 거부(큰 전송 차단)
    } catch {
      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
    }
    // 빠른 실패용 용량 precheck(최종 형식·모델 게이팅은 finalize의 stageBuffer에서). 음성·영상 100MB / 그 외 500MB.
    const ext = extOf(filename);
    const cap = capBytesFor(ext, mime);
    if (size > cap) {
      const isAV = isAudioVideoExt(ext, mime);
      return NextResponse.json({ error: `파일은 ${Math.round(cap / 1024 / 1024)}MB 이하만 가능합니다.${isAV ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 413 });
    }
    const meta = await createChunkSession({
      userId: user.id, scope, filename, mime,
      title: String(body.title || ""), anonymous: Boolean(body.anonymous), geminiOptIn: Boolean(body.geminiOptIn), size,
    });
    return NextResponse.json({ uploadId: meta.uploadId, chunkSize: CHUNK_BYTES, received: 0 });
  }

  if (action === "finalize") {
    const uploadId = String(body.uploadId || "");
    const meta = await getChunkSession(uploadId).catch(() => null);
    if (!meta) return NextResponse.json({ error: "업로드 세션을 찾을 수 없습니다." }, { status: 404 });
    if (meta.userId !== user.id) return NextResponse.json({ error: "이 업로드의 소유자가 아닙니다." }, { status: 403 });
    try {
      const { tempPath } = await chunkSessionTempPath(uploadId);
      const buf = await readFile(tempPath); // 1회 적재(추출·보관용) — 4Gi limit 내(§11.1)
      const res = await stageBuffer(user, buf, meta.filename, meta.mime, {
        scope: meta.scope, title: meta.title, anonymous: meta.anonymous, diarize: false, geminiOptIn: meta.geminiOptIn, modelField: "",
      });
      return res;
    } catch (err) {
      return NextResponse.json({ error: String(err) }, { status: 400 });
    } finally {
      await cleanupChunkSession(uploadId);
    }
  }

  return NextResponse.json({ error: "알 수 없는 action입니다(create|finalize)." }, { status: 400 });
}

// 청크 append — octet-stream 본문, offset은 쿼리스트링. received/complete 반환. gap이면 409 + 현재 received.
export async function PATCH(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const u = new URL(req.url);
  const uploadId = u.searchParams.get("uploadId") || "";
  const offset = Number(u.searchParams.get("offset"));
  if (!Number.isInteger(offset) || offset < 0) return NextResponse.json({ error: "유효한 offset이 필요합니다." }, { status: 400 });
  const meta = await getChunkSession(uploadId).catch(() => null);
  if (!meta) return NextResponse.json({ error: "업로드 세션을 찾을 수 없습니다(만료되었거나 다른 서버일 수 있어요)." }, { status: 404 });
  if (meta.userId !== user.id) return NextResponse.json({ error: "이 업로드의 소유자가 아닙니다." }, { status: 403 });
  if (!req.body) return NextResponse.json({ error: "청크 본문이 비었습니다." }, { status: 400 });
  const chunk = Buffer.from(await req.arrayBuffer());
  try {
    const { received, complete } = await appendChunk(uploadId, offset, chunk);
    return NextResponse.json({ received, complete });
  } catch (err) {
    if (err instanceof ChunkGapError) {
      // 클라가 received부터 다시 보내도록 — 재개 지점 동봉(409 Conflict).
      return NextResponse.json({ error: err.message, received: err.expected }, { status: 409 });
    }
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

// 진행 상태(재개 지점 확인). 소유자만.
export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const uploadId = new URL(req.url).searchParams.get("uploadId") || "";
  const meta = await getChunkSession(uploadId).catch(() => null);
  if (!meta) return NextResponse.json({ error: "업로드 세션을 찾을 수 없습니다." }, { status: 404 });
  if (meta.userId !== user.id) return NextResponse.json({ error: "이 업로드의 소유자가 아닙니다." }, { status: 403 });
  return NextResponse.json({ uploadId: meta.uploadId, received: meta.received, size: meta.size, complete: meta.received >= meta.size });
}

