// ── 청크/resumable 업로드 클라이언트(PLAN-remaining-backlog-design §8) ──────────────────────
// 큰 파일을 고정 크기 청크로 나눠 순차 전송하고, 네트워크 오류·청크 실패 시 ★그 지점부터 재시도★한다.
//   서버는 /api/materials/upload (create→PATCH append→finalize). File.slice(Blob)를 body로 보내 클라도 RAM
//   통적재를 피한다(스트리밍). 진행률 콜백으로 업로드 % 표시 가능.
// ★ship-dark★: NEXT_PUBLIC_CHUNKED_UPLOAD="true"일 때만 큰 파일에 사용(아니면 기존 octet-stream 경로).

export function chunkedUploadEnabled(): boolean {
  return process.env.NEXT_PUBLIC_CHUNKED_UPLOAD === "true";
}

export interface ChunkedUploadOpts { scope: string; title?: string; anonymous?: boolean; geminiOptIn?: boolean }

const MAX_CHUNK_RETRIES = 4;
const RETRY_DELAY_MS = 800;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * 파일을 청크로 업로드하고 finalize 결과(JSON)를 반환한다. 기존 단건 업로드와 동일한 응답 형태
 * (sourceId·status·recommended 등)라 호출측 toStaged가 그대로 소비한다.
 * @returns { ok, status, data } — data는 finalize(=stageBuffer) JSON.
 */
export async function chunkedUpload(
  file: File,
  opts: ChunkedUploadOpts,
  onProgress?: (sent: number, total: number) => void,
  signal?: AbortSignal,
): Promise<{ ok: boolean; status: number; data: Record<string, unknown> }> {
  // 1) 세션 생성
  const createRes = await fetch("/api/materials/upload", {
    method: "POST", headers: { "content-type": "application/json" }, signal,
    body: JSON.stringify({ action: "create", scope: opts.scope, filename: file.name, size: file.size, mime: file.type || "", title: opts.title, anonymous: opts.anonymous, geminiOptIn: opts.geminiOptIn }),
  });
  const created = await createRes.json().catch(() => ({}));
  if (!createRes.ok) return { ok: false, status: createRes.status, data: created };
  const uploadId: string = created.uploadId;
  const chunkSize: number = created.chunkSize || 8 * 1024 * 1024;

  // 2) 청크 순차 전송(실패 청크만 재시도, 409 gap이면 서버가 알려준 offset으로 재동기화)
  let offset = 0;
  while (offset < file.size) {
    if (signal?.aborted) throw new DOMException("Aborted", "AbortError");
    const end = Math.min(offset + chunkSize, file.size);
    const blob = file.slice(offset, end);
    let attempt = 0;
    for (;;) {
      try {
        const res = await fetch(`/api/materials/upload?uploadId=${encodeURIComponent(uploadId)}&offset=${offset}`, {
          method: "PATCH", headers: { "content-type": "application/octet-stream" }, body: blob, signal,
        });
        if (res.status === 409) {
          // gap: 서버가 기대하는 received로 점프(중복/누락 보정).
          const d = await res.json().catch(() => ({}));
          if (typeof d.received === "number") { offset = d.received; break; }
          throw new Error(d.error || "청크 동기화 실패");
        }
        if (!res.ok) {
          const d = await res.json().catch(() => ({}));
          throw new Error(d.error || `청크 업로드 실패(${res.status})`);
        }
        const d = await res.json();
        offset = typeof d.received === "number" ? d.received : end; // 서버 received를 신뢰(재개 정합)
        onProgress?.(offset, file.size);
        break;
      } catch (e) {
        if (signal?.aborted || (e instanceof DOMException && e.name === "AbortError")) throw e;
        if (++attempt > MAX_CHUNK_RETRIES) throw e;
        await sleep(RETRY_DELAY_MS * attempt); // 점증 백오프
        // 재시도 전 실제 서버 진행상태로 재동기화(중복 전송 회피).
        try {
          const st = await fetch(`/api/materials/upload?uploadId=${encodeURIComponent(uploadId)}`, { signal });
          if (st.ok) { const sd = await st.json(); if (typeof sd.received === "number") offset = sd.received; }
        } catch { /* status 실패는 무시하고 같은 offset 재시도 */ }
      }
    }
  }

  // 3) finalize → stageBuffer 결과 반환
  const finRes = await fetch("/api/materials/upload", {
    method: "POST", headers: { "content-type": "application/json" }, signal,
    body: JSON.stringify({ action: "finalize", uploadId }),
  });
  const finData = await finRes.json().catch(() => ({}));
  return { ok: finRes.ok, status: finRes.status, data: finData };
}

