1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { assertScopeAllowed, scopeWikiPrefix } from "@/lib/acl/scope";
4	import { storeForAnalysis, storeRawOnly } from "@/lib/ingest";
5	import { extractAsset, SUPPORTED_EXTS, STT_EXTS } from "@/lib/extract";
6	import { STT_FFMPEG_EXTS, sttAvailable, sttAsync, isTranscribedExtractor } from "@/lib/stt";
7	import { CONVERT_ONLY_EXTS, libreOfficeAvailable, ffmpegAvailable } from "@/lib/convert";
8	import { uploadPolicyForModel } from "@/lib/uploadPolicy";
9	import { resolveIngestModel, recommendIngestModel } from "@/lib/models";
10	
11	// 업로드 스테이징 공유 코어 — multipart·raw-body 스트리밍·★청크/resumable★(app/api/materials/upload) 세 진입점이
12	//   ★같은 게이팅·추출·보관 불변식★을 공유한다(전수 점검 원칙 [[sweep-all-dont-claim-fixed]] — 중복 구현 금지).
13	
14	// 업로드 용량 상한(MB). 음성·영상은 L1 청크 전사로 긴 회의 수용(100), 문서는 L3a 스트리밍으로 상향(500).
15	export const CAP_MB_AUDIO_VIDEO = 100;
16	export const CAP_MB_DOC = 500; // L3a 스트리밍 업로드 + L3b 응축(거대 텍스트 분석 가능) → 500MB. Ingress 512m와 정합.
17	export const STREAM_THRESHOLD = 25 * 1024 * 1024; // 이 이상은 raw-body 스트리밍/청크 권장(클라/서버 공통 기준)
18	
19	export type SessionUser = NonNullable<Awaited<ReturnType<typeof getSessionUser>>>;
20	export interface StageOpts { scope: string; title: string; anonymous: boolean; diarize: boolean; modelField: string; geminiOptIn?: boolean }
21	
22	/** 파일 확장자가 음성·영상(STT 대상)인지 — 용량 cap 분기용(순수). */
23	export function isAudioVideoExt(ext: string, mimeType = ""): boolean {
24	  return mimeType.startsWith("audio/") || mimeType.startsWith("video/") || STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
25	}
26	
27	/** 확장자(+mime)별 업로드 용량 상한(바이트). 음성·영상 100MB, 그 외 500MB. */
28	export function capBytesFor(ext: string, mimeType = ""): number {
29	  return (isAudioVideoExt(ext, mimeType) ? CAP_MB_AUDIO_VIDEO : CAP_MB_DOC) * 1024 * 1024;
30	}
31	
32	// 업로드 버퍼 1건을 ★스테이징★(게이팅→추출→보관, 토큰 0)한다. multipart·raw-body·청크 finalize가 공유.
33	//   ACL 강제지점3·형식/모델 게이팅·용량 cap·추출(docs/17)·원본 보존을 한 곳에 모아 경로 간 불일치를 막는다.
34	export async function stageBuffer(user: SessionUser, buf: Buffer, filename: string, mimeType: string, opts: StageOpts): Promise<NextResponse> {
35	  const { scope, anonymous, diarize, modelField } = opts;
36	  try {
37	    await assertScopeAllowed(user, scope); // ACL 강제지점3
38	  } catch {
39	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
40	  }
41	  // 사용자가 자료 탭에서 고른 인제스트 모델(검증·폴백) → ★그 모델★ 능력 기준으로 게이팅·인제스트.
42	  const picked = await resolveIngestModel(modelField || undefined);
43	  const ext = (filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
44	  const pol = uploadPolicyForModel(picked.model, picked.provider);
