1	// ── 결정적 모순 검증 게이트 (B) ──────────────────────────────────────────────────
2	// 왜: 분석 모델에게 "지식 추출 + 모순 탐지 + 자기보고(needs_human)"를 한꺼번에 시키면 강한 모델
3	//   (codex·Gemini·Claude 포함)도 모순을 자주 놓친다(자기보고 불안정 → 거의 항상 자동적용). 실제로 같은
4	//   대상에 상충하는 사실을 올려도 confidence 0.9로 AUTO_APPLIED 되어 검토 콘솔에 안 올라오는 게 관찰됨.
5	// 해결: 분석과 ★분리된 전용 검증 패스★를 돌리고, 그 결과로 ★코드가 게이트를 강제★한다(분석 모델의 변덕과 무관).
6	//   기존 위키의 단정적 사실(예: "킹스커피에서 가장 잘 팔리는 메뉴 = 아이스아메리카노")과 새 자료가 직접
7	//   충돌하면 자동적용을 막고 검토 콘솔로 보낸다(사유 첨부). 제목이 달라도(카페 vs 카페 메뉴) 주제 토큰으로 잡는다.
8	// 비용 가드([[user-cost-sensitivity]]): 모든 인제스트가 아니라 ① 자동적용 후보이고 ② 주제가 겹치는 기존
9	//   페이지가 있을 때만(순수 사전필터 existingPagesAtRisk) 검증 LLM 1콜. 신규/첫 업로드는 0원(건너뜀).
10	//   INGEST_CONTRADICTION_CHECK=false 로 전체 비활성. 설계: docs/06-ingest-pipeline §모순 검증 게이트.
11	import type { WikiEdit } from "./wiki/applyEditSet";
12	import type { WikiPage } from "./wiki/context";
13	
14	export interface Contradiction {
15	  subject: string;  // 무엇에 대한 충돌인가 (예: "킹스커피에서 가장 잘 팔리는 메뉴")
16	  existing: string; // 기존 위키가 말하는 값
17	  incoming: string; // 새 자료가 말하는 값
18	  page?: string;    // 충돌하는 기존 페이지 경로(있으면)
19	}
20	export interface ContradictionResult { hasContradiction: boolean; contradictions: Contradiction[] }
21	
22	// 전용 검증 패스의 구조화 출력 스키마(report_contradictions 도구).
23	export const CONTRADICTION_SCHEMA: Record<string, unknown> = {
24	  type: "object",
25	  properties: {
26	    hasContradiction: { type: "boolean", description: "명백한 사실 충돌이 하나라도 있으면 true" },
27	    contradictions: {
28	      type: "array",
29	      description: "양립 불가한 직접 충돌만. 보강·추가·표현차이는 넣지 않는다.",
30	      items: {
31	        type: "object",
32	        properties: {
33	          subject: { type: "string", description: "충돌하는 대상/사실 (예: '킹스커피에서 가장 잘 팔리는 메뉴')" },
34	          existing: { type: "string", description: "기존 위키가 말하는 값" },
35	          incoming: { type: "string", description: "새 자료가 말하는 값" },
36	          page: { type: "string", description: "충돌하는 기존 페이지 경로(알면)" },
37	        },
38	        required: ["subject", "existing", "incoming"],
39	      },
40	    },
41	  },
42	  required: ["hasContradiction", "contradictions"],
43	};
44	
45	/** 전체 비활성 스위치(기본 ON). 운영에서 끄려면 INGEST_CONTRADICTION_CHECK=false. */
46	export function contradictionCheckEnabled(): boolean {
47	  return process.env.INGEST_CONTRADICTION_CHECK !== "false";
48	}
49	
50	/**
51	 * 모순 검사에 쓸 ★강한 모델★ 선택(순수) — 분석이 약한 무료 오픈모델(Groq llama 등)로 폴백해도 검사 품질이
52	 *   떨어지면 모순을 놓친다(운영서 관찰). isStrong(provider)=true인 후보만 검사에 쓰고, 없으면 Gemini를 최후
53	 *   보루로(무료 강한). 강한 게 하나도 없으면 null(약한 모델로 검사하느니 스킵=best-effort). isStrong은 호출측이
54	 *   promptTier로 주입(드리프트 방지·테스트 용이).
55	 */
56	// 검사 후보 = 모델·공급자·(비전여부). 비전은 검사에 안 쓰지만 폴백 타입(FallbackTarget) 호환을 위해 유지.
57	export interface CheckCandidate { model: string; provider: string; vision: boolean }
58	export function pickStrongCheckModel(
59	  model: string,
60	  provider: string,
61	  fallbacks: CheckCandidate[],
62	  isStrong: (provider: string) => boolean,
63	  isAllowed: (model: string) => boolean = () => true, // ★관리자가 끈 모델 제외★(활성 모델만 검사에 사용)
64	): { model: string; provider: string; fallbacks: CheckCandidate[] } | null {
65	  const cands: CheckCandidate[] = [{ model, provider, vision: false }, ...(fallbacks ?? [])]
66	    .filter((c) => !!c.provider && isStrong(c.provider) && isAllowed(c.model));
67	  // 최후 보루(무료 강한) — 단, ★관리자가 gemini를 끈 경우엔 추가하지 않는다★.
68	  if (!cands.some((c) => c.provider === "gemini") && isAllowed("gemini-2.5-flash")) {
69	    cands.push({ model: "gemini-2.5-flash", provider: "gemini", vision: true });
70	  }
71	  if (!cands.length) return null;
72	  return { model: cands[0].model, provider: cands[0].provider, fallbacks: cands.slice(1) };
73	}
74	
75	// 경로 정규화(슬래시·접두 통일) — 같은 페이지를 다시 쓰는지 비교용.
76	function normPath(p: string): string {
77	  return String(p ?? "").trim().replace(/\\/g, "/").replace(/^\.?\/+/, "").replace(/^wiki\//, "");
78	}
79	
80	// 실제 페이지를 만드는 콘텐츠 편집만(빈 op·빈 content 제외).
81	function contentEdits(edits: WikiEdit[] | null | undefined): WikiEdit[] {
82	  return (edits ?? []).filter((e) => (e?.op === "create" || e?.op === "append") && !!e.path && (e.content ?? "").trim().length > 0);
83	}
84	
85	// 한국어 조사 — 붙어 있으면 떼낸 어간도 토큰에 넣어 '킹스커피에서'와 '킹스커피는'이 같은 '킹스커피'로 만난다.
86	//   (lib/glossary.ts와 동일 철학) 긴 것 우선 매칭.
87	const JOSA = ["으로", "에서", "에게", "이라", "라는", "까지", "부터", "처럼", "마다", "보다", "에는", "으론",
88	  "은", "는", "이", "가", "을", "를", "의", "에", "와", "과", "로", "도", "만", "요", "께"]
89	  .sort((a, b) => b.length - a.length);
90	
91	// 유의미 토큰(한글·영문·숫자, 길이≥2). 영문 소문자화 + 한글은 조사를 뗀 어간도 함께 수록. 주제 겹침 판정용(순수).
92	//   조사를 잘못 떼어 어간이 더 생겨도 ‘겹침 후보 약간 증가(추가 1콜 가능)’일 뿐 — 충돌 판단은 LLM이 하므로 안전.
93	export function salientTokens(text: string): Set<string> {
94	  const out = new Set<string>();
95	  for (const m of String(text ?? "").matchAll(/[\p{L}\p{N}]+/gu)) {
96	    const t = m[0].toLowerCase();
97	    if (t.length >= 2) out.add(t);
98	    if (/[가-힣]/.test(t)) {
99	      for (const j of JOSA) {
100	        if (t.length > j.length + 1 && t.endsWith(j)) { out.add(t.slice(0, -j.length)); break; }
101	      }
102	    }
103	  }
104	  return out;
105	}
106	
107	/**
108	 * 새 편집셋과 ★주제가 겹치는 기존 페이지★만 추린다(순수·비용 사전필터). 겹치는 게 없으면 검증 콜을 건너뛴다.
109	 * 판정: ① 같은 path를 다시 씀 = 최우선, ② 긴 토큰(≈고유명사, 길이≥4) 1개 공유, 또는 ③ 일반 토큰 2개+ 공유.
110	 *   → 제목이 달라도('카페' vs '카페 메뉴') 본문에 공통으로 등장하는 고유명사('킹스커피')로 잡는다.
111	 * 거짓양성(무관 페이지 약간 포함)은 비용만 늘 뿐 — 충돌 판단은 LLM이 하므로 잘못된 검토를 만들지 않는다.
112	 */
113	export function existingPagesAtRisk(
114	  existingPages: WikiPage[] | null | undefined,
115	  edits: WikiEdit[] | null | undefined,
116	  opts: { maxPages?: number } = {},
117	): WikiPage[] {
118	  const maxPages = opts.maxPages ?? 6;
119	  const ce = contentEdits(edits);
120	  const pages = existingPages ?? [];
121	  if (!pages.length || !ce.length) return [];
122	  const editPaths = new Set(ce.map((e) => normPath(e.path)));
123	  const incoming = salientTokens(ce.map((e) => e.content).join("\n"));
124	  const scored: { p: WikiPage; score: number }[] = [];
125	  for (const p of pages) {
126	    if (editPaths.has(normPath(p.path))) { scored.push({ p, score: 100 }); continue; } // 같은 페이지 재작성 = 최우선
127	    const pt = salientTokens(p.content);
128	    let shared = 0, sharedLong = 0;
129	    for (const t of incoming) if (pt.has(t)) { shared++; if (t.length >= 4) sharedLong++; }
130	    const score = sharedLong >= 1 ? 10 + sharedLong * 2 + shared : (shared >= 2 ? shared : 0);
131	    if (score > 0) scored.push({ p, score });
132	  }
133	  scored.sort((a, b) => b.score - a.score);
134	  return scored.slice(0, maxPages).map((s) => s.p);
135	}
136	
137	// ★모순 '대체' 해소(순수)★ — 검토 승인 시 '새 정보로 대체'할 때 ★아카이브할 기존 충돌 페이지★ 목록.
138	//   contradictions[].page 중 ① 콘텐츠 페이지(.md)이고 ② 이번에 적용된 페이지(changedPaths)가 ★아닌★ 것만.
139	//   (방금 갱신된 페이지=새 정보이므로 보존; 충돌하던 기존 페이지만 아카이브해 위키에 최신 하나만 남긴다.)
140	export function pagesToSupersede(
141	  contradictions: { page?: string }[] | undefined,
142	  changedPaths: string[],
143	): string[] {
144	  const norm = (p: string) => p.trim().replace(/\\/g, "/").replace(/^\.?\/+/, "").replace(/^wiki\//, "");
145	  const changed = new Set((changedPaths ?? []).map(norm));
146	  const out = new Set<string>();
147	  for (const c of contradictions ?? []) {
148	    const p = (c?.page ?? "").trim();
149	    if (!p.endsWith(".md") || !/\/(entities|concepts|topics)\/[^/]+\.md$/.test(p)) continue;
150	    if (changed.has(norm(p))) continue;
151	    out.add(p);
152	  }
153	  return [...out];
154	}
155	
156	// 본문 절단(토큰 절감). 프롬프트 빌더용.
157	function truncate(s: string, cap: number): string {
158	  return s.length <= cap ? s : s.slice(0, cap) + "\n…(이하 생략)";
159	}
160	
161	/** 전용 검증 패스 프롬프트(순수). 거짓양성 최소화: 보강·추가·표현차이는 충돌이 아님을 강하게 명시. */
162	export function buildContradictionPrompt(
163	  atRisk: WikiPage[],
164	  edits: WikiEdit[],
165	  opts: { bodyCap?: number } = {},
166	): { system: string; userText: string } {
167	  const bodyCap = opts.bodyCap ?? 2500;
168	  const existing = atRisk.map((p) => `### 기존 페이지: ${p.path}\n${truncate(p.content, bodyCap)}`).join("\n\n");
169	  const incoming = contentEdits(edits).map((e) => `### 새 편집(${e.op}): ${e.path}\n${truncate(e.content, bodyCap)}`).join("\n\n");
170	  const system = [
171	    "당신은 위키 사실 검증자입니다. 아래 '기존 위키 페이지'와 '새 자료의 편집'을 비교해,",
172	    "★단정적 사실이 직접 충돌(같은 대상에 대해 양립 불가한 다른 값)★하는 항목만 찾으세요.",
173	    "충돌의 예: 같은 주체의 '가장 잘 팔리는 메뉴'가 기존 'A' ↔ 새 'B' / 수치·날짜·담당자·상태가 서로 다름.",
174	    "충돌이 아님(절대 넣지 말 것): 새 정보가 기존을 보강·추가만 함(상충 없음), 서로 다른 대상을 다룸, 표현만 다름.",
175	    "★기존값이 실제로 존재할 때만★: '기존 위키'에 그 사실의 ★구체적 값이 명시★돼 있고 새 값과 ★양립 불가★일 때만 충돌이다.",
176	    "  기존에 그 사실이 없으면(모르면) 충돌이 아니라 새 정보다 — existing을 '알 수 없음/없음' 따위로 채워 충돌로 보고하지 말 것.",
177	    "  ※ 서로 다른 대상(예: A사 1위 메뉴 vs B사 1위 메뉴)은 ★같은 대상이 아니므로 충돌 아님★.",
178	    "애매하면 충돌로 보지 마세요(거짓양성 최소화) — ★명백히 양립 불가할 때만★ 보고합니다.",
179	    "report_contradictions 도구로만 답합니다. 충돌이 없으면 hasContradiction=false, contradictions=[].",
180	  ].join("\n");
181	  const userText = `[기존 위키]\n${existing}\n\n[새 자료의 편집]\n${incoming}`;
182	  return { system, userText };
183	}
184	
185	// '실제 기존값이 없음'을 뜻하는 표현 — 이런 existing은 충돌이 아니라 ★새 정보★다(거짓양성 차단).
186	//   진짜 모순은 기존 페이지에 ★구체적 값이 명시★돼 있고 그게 새 값과 양립 불가일 때만.
187	function isUnknownValue(s: string): boolean {
188	  const t = s.trim().toLowerCase().replace(/\s+/g, "");
189	  if (!t || t === "-" || t === "n/a" || t === "na" || t === "unknown" || t === "none" || t === "null") return true;
190	  return /^(알수없음|없음|없습니다|해당없음|모름|미상|정보없음|명시되지않음|기존없음|언급없음|불명)/.test(t);
191	}
192	
193	// LLM 원시 출력을 안전한 ContradictionResult로 정규화(방어적). 비정상이면 충돌 없음으로 간주(인제스트를 막지 않음).
194	export function normalizeContradictionResult(raw: unknown): ContradictionResult {
195	  const r = (raw ?? {}) as { hasContradiction?: unknown; contradictions?: unknown };
196	  const list = Array.isArray(r.contradictions) ? r.contradictions : [];
197	  const contradictions: Contradiction[] = list
198	    .map((c) => {
199	      const o = (c ?? {}) as Record<string, unknown>;
200	      const subject = String(o.subject ?? "").trim();
201	      const existing = String(o.existing ?? "").trim();
202	      const incoming = String(o.incoming ?? "").trim();
203	      // ★진짜 충돌만★: subject·existing·incoming 모두 구체적이어야 하고, 기존값이 '알 수 없음'류면 새 정보일 뿐(거짓양성).
204	      if (!subject || !existing || !incoming) return null;
205	      if (isUnknownValue(existing) || isUnknownValue(incoming)) return null;
206	      if (existing.trim() === incoming.trim()) return null; // 같은 값 = 충돌 아님
207	      const page = o.page ? String(o.page).trim() : undefined;
208	      return { subject, existing, incoming, ...(page ? { page } : {}) } as Contradiction;
209	    })
210	    .filter((c): c is Contradiction => c !== null);
211	  // hasContradiction은 ★실제 항목 존재★를 단일 진실로(모델이 true라 해놓고 빈 배열 주는 변덕 방지).
212	  const hasContradiction = contradictions.length > 0 && r.hasContradiction !== false;
213	  return { hasContradiction, contradictions: hasContradiction ? contradictions : [] };
214	}
215	
216	/**
217	 * 모순 검증 — 주제가 겹치는 기존 페이지가 있을 때만 주입된 llm으로 1콜. 겹침 없으면 콜 없이 충돌 없음 반환(0원).
218	 * @param llm 프롬프트→원시 결과. ingest.ts가 callStructured로 감싸 주입(테스트는 가짜 llm 주입).
219	 */
220	export async function findContradictions(args: {
221	  existingPages: WikiPage[];
222	  edits: WikiEdit[];
223	  llm: (p: { system: string; userText: string }) => Promise<unknown>;
224	  maxPages?: number;
225	  bodyCap?: number;
226	}): Promise<ContradictionResult> {
227	  const atRisk = existingPagesAtRisk(args.existingPages, args.edits, { maxPages: args.maxPages });
228	  if (!atRisk.length) return { hasContradiction: false, contradictions: [] };
229	  const prompt = buildContradictionPrompt(atRisk, args.edits, { bodyCap: args.bodyCap });
230	  const raw = await args.llm(prompt);
231	  return normalizeContradictionResult(raw);
232	}
233

