// ── 결정적 모순 검증 게이트 (B) ──────────────────────────────────────────────────
// 왜: 분석 모델에게 "지식 추출 + 모순 탐지 + 자기보고(needs_human)"를 한꺼번에 시키면 강한 모델
//   (codex·Gemini·Claude 포함)도 모순을 자주 놓친다(자기보고 불안정 → 거의 항상 자동적용). 실제로 같은
//   대상에 상충하는 사실을 올려도 confidence 0.9로 AUTO_APPLIED 되어 검토 콘솔에 안 올라오는 게 관찰됨.
// 해결: 분석과 ★분리된 전용 검증 패스★를 돌리고, 그 결과로 ★코드가 게이트를 강제★한다(분석 모델의 변덕과 무관).
//   기존 위키의 단정적 사실(예: "킹스커피에서 가장 잘 팔리는 메뉴 = 아이스아메리카노")과 새 자료가 직접
//   충돌하면 자동적용을 막고 검토 콘솔로 보낸다(사유 첨부). 제목이 달라도(카페 vs 카페 메뉴) 주제 토큰으로 잡는다.
// 비용 가드([[user-cost-sensitivity]]): 모든 인제스트가 아니라 ① 자동적용 후보이고 ② 주제가 겹치는 기존
//   페이지가 있을 때만(순수 사전필터 existingPagesAtRisk) 검증 LLM 1콜. 신규/첫 업로드는 0원(건너뜀).
//   INGEST_CONTRADICTION_CHECK=false 로 전체 비활성. 설계: docs/06-ingest-pipeline §모순 검증 게이트.
import type { WikiEdit } from "./wiki/applyEditSet";
import type { WikiPage } from "./wiki/context";

export interface Contradiction {
  subject: string;  // 무엇에 대한 충돌인가 (예: "킹스커피에서 가장 잘 팔리는 메뉴")
  existing: string; // 기존 위키가 말하는 값
  incoming: string; // 새 자료가 말하는 값
  page?: string;    // 충돌하는 기존 페이지 경로(있으면)
}
export interface ContradictionResult { hasContradiction: boolean; contradictions: Contradiction[] }

// 전용 검증 패스의 구조화 출력 스키마(report_contradictions 도구).
export const CONTRADICTION_SCHEMA: Record<string, unknown> = {
  type: "object",
  properties: {
    hasContradiction: { type: "boolean", description: "명백한 사실 충돌이 하나라도 있으면 true" },
    contradictions: {
      type: "array",
      description: "양립 불가한 직접 충돌만. 보강·추가·표현차이는 넣지 않는다.",
      items: {
        type: "object",
        properties: {
          subject: { type: "string", description: "충돌하는 대상/사실 (예: '킹스커피에서 가장 잘 팔리는 메뉴')" },
          existing: { type: "string", description: "기존 위키가 말하는 값" },
          incoming: { type: "string", description: "새 자료가 말하는 값" },
          page: { type: "string", description: "충돌하는 기존 페이지 경로(알면)" },
        },
        required: ["subject", "existing", "incoming"],
      },
    },
  },
  required: ["hasContradiction", "contradictions"],
};

/** 전체 비활성 스위치(기본 ON). 운영에서 끄려면 INGEST_CONTRADICTION_CHECK=false. */
export function contradictionCheckEnabled(): boolean {
  return process.env.INGEST_CONTRADICTION_CHECK !== "false";
}

/**
 * 모순 검사에 쓸 ★강한 모델★ 선택(순수) — 분석이 약한 무료 오픈모델(Groq llama 등)로 폴백해도 검사 품질이
 *   떨어지면 모순을 놓친다(운영서 관찰). isStrong(provider)=true인 후보만 검사에 쓰고, 없으면 Gemini를 최후
 *   보루로(무료 강한). 강한 게 하나도 없으면 null(약한 모델로 검사하느니 스킵=best-effort). isStrong은 호출측이
 *   promptTier로 주입(드리프트 방지·테스트 용이).
 */
// 검사 후보 = 모델·공급자·(비전여부). 비전은 검사에 안 쓰지만 폴백 타입(FallbackTarget) 호환을 위해 유지.
export interface CheckCandidate { model: string; provider: string; vision: boolean }
export function pickStrongCheckModel(
  model: string,
  provider: string,
  fallbacks: CheckCandidate[],
  isStrong: (provider: string) => boolean,
  isAllowed: (model: string) => boolean = () => true, // ★관리자가 끈 모델 제외★(활성 모델만 검사에 사용)
): { model: string; provider: string; fallbacks: CheckCandidate[] } | null {
  const cands: CheckCandidate[] = [{ model, provider, vision: false }, ...(fallbacks ?? [])]
    .filter((c) => !!c.provider && isStrong(c.provider) && isAllowed(c.model));
  // 최후 보루(무료 강한) — 단, ★관리자가 gemini를 끈 경우엔 추가하지 않는다★.
  if (!cands.some((c) => c.provider === "gemini") && isAllowed("gemini-2.5-flash")) {
    cands.push({ model: "gemini-2.5-flash", provider: "gemini", vision: true });
  }
  if (!cands.length) return null;
  return { model: cands[0].model, provider: cands[0].provider, fallbacks: cands.slice(1) };
}

// 경로 정규화(슬래시·접두 통일) — 같은 페이지를 다시 쓰는지 비교용.
function normPath(p: string): string {
  return String(p ?? "").trim().replace(/\\/g, "/").replace(/^\.?\/+/, "").replace(/^wiki\//, "");
}

// 실제 페이지를 만드는 콘텐츠 편집만(빈 op·빈 content 제외).
function contentEdits(edits: WikiEdit[] | null | undefined): WikiEdit[] {
  return (edits ?? []).filter((e) => (e?.op === "create" || e?.op === "append") && !!e.path && (e.content ?? "").trim().length > 0);
}

// 한국어 조사 — 붙어 있으면 떼낸 어간도 토큰에 넣어 '킹스커피에서'와 '킹스커피는'이 같은 '킹스커피'로 만난다.
//   (lib/glossary.ts와 동일 철학) 긴 것 우선 매칭.
const JOSA = ["으로", "에서", "에게", "이라", "라는", "까지", "부터", "처럼", "마다", "보다", "에는", "으론",
  "은", "는", "이", "가", "을", "를", "의", "에", "와", "과", "로", "도", "만", "요", "께"]
  .sort((a, b) => b.length - a.length);

// 유의미 토큰(한글·영문·숫자, 길이≥2). 영문 소문자화 + 한글은 조사를 뗀 어간도 함께 수록. 주제 겹침 판정용(순수).
//   조사를 잘못 떼어 어간이 더 생겨도 ‘겹침 후보 약간 증가(추가 1콜 가능)’일 뿐 — 충돌 판단은 LLM이 하므로 안전.
export function salientTokens(text: string): Set<string> {
  const out = new Set<string>();
  for (const m of String(text ?? "").matchAll(/[\p{L}\p{N}]+/gu)) {
    const t = m[0].toLowerCase();
    if (t.length >= 2) out.add(t);
    if (/[가-힣]/.test(t)) {
      for (const j of JOSA) {
        if (t.length > j.length + 1 && t.endsWith(j)) { out.add(t.slice(0, -j.length)); break; }
      }
    }
  }
  return out;
}

/**
 * 새 편집셋과 ★주제가 겹치는 기존 페이지★만 추린다(순수·비용 사전필터). 겹치는 게 없으면 검증 콜을 건너뛴다.
 * 판정: ① 같은 path를 다시 씀 = 최우선, ② 긴 토큰(≈고유명사, 길이≥4) 1개 공유, 또는 ③ 일반 토큰 2개+ 공유.
 *   → 제목이 달라도('카페' vs '카페 메뉴') 본문에 공통으로 등장하는 고유명사('킹스커피')로 잡는다.
 * 거짓양성(무관 페이지 약간 포함)은 비용만 늘 뿐 — 충돌 판단은 LLM이 하므로 잘못된 검토를 만들지 않는다.
 */
export function existingPagesAtRisk(
  existingPages: WikiPage[] | null | undefined,
  edits: WikiEdit[] | null | undefined,
  opts: { maxPages?: number } = {},
): WikiPage[] {
  const maxPages = opts.maxPages ?? 6;
  const ce = contentEdits(edits);
  const pages = existingPages ?? [];
  if (!pages.length || !ce.length) return [];
  const editPaths = new Set(ce.map((e) => normPath(e.path)));
  const incoming = salientTokens(ce.map((e) => e.content).join("\n"));
  const scored: { p: WikiPage; score: number }[] = [];
  for (const p of pages) {
    if (editPaths.has(normPath(p.path))) { scored.push({ p, score: 100 }); continue; } // 같은 페이지 재작성 = 최우선
    const pt = salientTokens(p.content);
    let shared = 0, sharedLong = 0;
    for (const t of incoming) if (pt.has(t)) { shared++; if (t.length >= 4) sharedLong++; }
    const score = sharedLong >= 1 ? 10 + sharedLong * 2 + shared : (shared >= 2 ? shared : 0);
    if (score > 0) scored.push({ p, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, maxPages).map((s) => s.p);
}

// ★모순 '대체' 해소(순수)★ — 검토 승인 시 '새 정보로 대체'할 때 ★아카이브할 기존 충돌 페이지★ 목록.
//   contradictions[].page 중 ① 콘텐츠 페이지(.md)이고 ② 이번에 적용된 페이지(changedPaths)가 ★아닌★ 것만.
//   (방금 갱신된 페이지=새 정보이므로 보존; 충돌하던 기존 페이지만 아카이브해 위키에 최신 하나만 남긴다.)
export function pagesToSupersede(
  contradictions: { page?: string }[] | undefined,
  changedPaths: string[],
): string[] {
  const norm = (p: string) => p.trim().replace(/\\/g, "/").replace(/^\.?\/+/, "").replace(/^wiki\//, "");
  const changed = new Set((changedPaths ?? []).map(norm));
  const out = new Set<string>();
  for (const c of contradictions ?? []) {
    const p = (c?.page ?? "").trim();
    if (!p.endsWith(".md") || !/\/(entities|concepts|topics)\/[^/]+\.md$/.test(p)) continue;
    if (changed.has(norm(p))) continue;
    out.add(p);
  }
  return [...out];
}

// 본문 절단(토큰 절감). 프롬프트 빌더용.
function truncate(s: string, cap: number): string {
  return s.length <= cap ? s : s.slice(0, cap) + "\n…(이하 생략)";
}

/** 전용 검증 패스 프롬프트(순수). 거짓양성 최소화: 보강·추가·표현차이는 충돌이 아님을 강하게 명시. */
export function buildContradictionPrompt(
  atRisk: WikiPage[],
  edits: WikiEdit[],
  opts: { bodyCap?: number } = {},
): { system: string; userText: string } {
  const bodyCap = opts.bodyCap ?? 2500;
  const existing = atRisk.map((p) => `### 기존 페이지: ${p.path}\n${truncate(p.content, bodyCap)}`).join("\n\n");
  const incoming = contentEdits(edits).map((e) => `### 새 편집(${e.op}): ${e.path}\n${truncate(e.content, bodyCap)}`).join("\n\n");
  const system = [
    "당신은 위키 사실 검증자입니다. 아래 '기존 위키 페이지'와 '새 자료의 편집'을 비교해,",
    "★단정적 사실이 직접 충돌(같은 대상에 대해 양립 불가한 다른 값)★하는 항목만 찾으세요.",
    "충돌의 예: 같은 주체의 '가장 잘 팔리는 메뉴'가 기존 'A' ↔ 새 'B' / 수치·날짜·담당자·상태가 서로 다름.",
    "충돌이 아님(절대 넣지 말 것): 새 정보가 기존을 보강·추가만 함(상충 없음), 서로 다른 대상을 다룸, 표현만 다름.",
    "★기존값이 실제로 존재할 때만★: '기존 위키'에 그 사실의 ★구체적 값이 명시★돼 있고 새 값과 ★양립 불가★일 때만 충돌이다.",
    "  기존에 그 사실이 없으면(모르면) 충돌이 아니라 새 정보다 — existing을 '알 수 없음/없음' 따위로 채워 충돌로 보고하지 말 것.",
    "  ※ 서로 다른 대상(예: A사 1위 메뉴 vs B사 1위 메뉴)은 ★같은 대상이 아니므로 충돌 아님★.",
    "애매하면 충돌로 보지 마세요(거짓양성 최소화) — ★명백히 양립 불가할 때만★ 보고합니다.",
    "report_contradictions 도구로만 답합니다. 충돌이 없으면 hasContradiction=false, contradictions=[].",
  ].join("\n");
  const userText = `[기존 위키]\n${existing}\n\n[새 자료의 편집]\n${incoming}`;
  return { system, userText };
}

// '실제 기존값이 없음'을 뜻하는 표현 — 이런 existing은 충돌이 아니라 ★새 정보★다(거짓양성 차단).
//   진짜 모순은 기존 페이지에 ★구체적 값이 명시★돼 있고 그게 새 값과 양립 불가일 때만.
function isUnknownValue(s: string): boolean {
  const t = s.trim().toLowerCase().replace(/\s+/g, "");
  if (!t || t === "-" || t === "n/a" || t === "na" || t === "unknown" || t === "none" || t === "null") return true;
  return /^(알수없음|없음|없습니다|해당없음|모름|미상|정보없음|명시되지않음|기존없음|언급없음|불명)/.test(t);
}

// LLM 원시 출력을 안전한 ContradictionResult로 정규화(방어적). 비정상이면 충돌 없음으로 간주(인제스트를 막지 않음).
export function normalizeContradictionResult(raw: unknown): ContradictionResult {
  const r = (raw ?? {}) as { hasContradiction?: unknown; contradictions?: unknown };
  const list = Array.isArray(r.contradictions) ? r.contradictions : [];
  const contradictions: Contradiction[] = list
    .map((c) => {
      const o = (c ?? {}) as Record<string, unknown>;
      const subject = String(o.subject ?? "").trim();
      const existing = String(o.existing ?? "").trim();
      const incoming = String(o.incoming ?? "").trim();
      // ★진짜 충돌만★: subject·existing·incoming 모두 구체적이어야 하고, 기존값이 '알 수 없음'류면 새 정보일 뿐(거짓양성).
      if (!subject || !existing || !incoming) return null;
      if (isUnknownValue(existing) || isUnknownValue(incoming)) return null;
      if (existing.trim() === incoming.trim()) return null; // 같은 값 = 충돌 아님
      const page = o.page ? String(o.page).trim() : undefined;
      return { subject, existing, incoming, ...(page ? { page } : {}) } as Contradiction;
    })
    .filter((c): c is Contradiction => c !== null);
  // hasContradiction은 ★실제 항목 존재★를 단일 진실로(모델이 true라 해놓고 빈 배열 주는 변덕 방지).
  const hasContradiction = contradictions.length > 0 && r.hasContradiction !== false;
  return { hasContradiction, contradictions: hasContradiction ? contradictions : [] };
}

/**
 * 모순 검증 — 주제가 겹치는 기존 페이지가 있을 때만 주입된 llm으로 1콜. 겹침 없으면 콜 없이 충돌 없음 반환(0원).
 * @param llm 프롬프트→원시 결과. ingest.ts가 callStructured로 감싸 주입(테스트는 가짜 llm 주입).
 */
export async function findContradictions(args: {
  existingPages: WikiPage[];
  edits: WikiEdit[];
  llm: (p: { system: string; userText: string }) => Promise<unknown>;
  maxPages?: number;
  bodyCap?: number;
}): Promise<ContradictionResult> {
  const atRisk = existingPagesAtRisk(args.existingPages, args.edits, { maxPages: args.maxPages });
  if (!atRisk.length) return { hasContradiction: false, contradictions: [] };
  const prompt = buildContradictionPrompt(atRisk, args.edits, { bodyCap: args.bodyCap });
  const raw = await args.llm(prompt);
  return normalizeContradictionResult(raw);
}

