21	async function canReview(user: User, teamScope: string): Promise<boolean> {
22	  if (user.role === "ADMIN") return true;
23	  if (teamScope === `personal/${user.id}`) return true;
24	  if (teamScope.startsWith("project-")) {
25	    const project = await prisma.project.findUnique({ where: { slug: teamScope.slice("project-".length) } });
26	    if (project) {
27	      const m = await prisma.projectMembership.findUnique({
28	        where: { userId_projectId: { userId: user.id, projectId: project.id } },
29	      });
30	      if (m?.role === "OWNER") return true;
31	    }
32	  }
33	  return false;
34	}
35	
36	// ── 변경 미리보기: 각 편집이 ★현재 위키 본문 대비★ 무엇을 추가/삭제하는지 줄 단위 diff로 반환 ──
37	//   create(기존 파일 있음)=전체 교체 → before/after diff, create(새 파일)·append=전부 추가.
38	export async function GET(_req: Request, { params }: { params: Promise<{ jobId: string }> }) {
