  // ★L2 reuse 모드★ — 기존 QUEUED 추적 잡(과 그 source)을 in-place로 갱신(삭제·재생성·dedup 없음).
  //   비동기 워커 전용 경로. 동기 경로는 아래 else로, 동작이 바뀌지 않는다.
  const existing = await prisma.ingestJob.findUnique({ where: { id: input.jobId } });
  if (!existing) return { status: "SKIPPED_DUP", sourceId: 0 }; // 취소·정리됨 → 조용히 종료
  source = await prisma.source.findUniqueOrThrow({ where: { id: existing.sourceId } });
  rawRel = source.rawPath;
  stem = rawRel.replace(/\.[^.]+$/, "");
  // ★동기 경로와 동일 규칙★: 새 정규화 텍스트가 있을 때만 사이드카 경로(아래 write 가드와 정합 — 없으면 null).
  //   DB의 normalizedPath는 새 값이 없으면 기존을 보존(아래 update의 ?? source.normalizedPath).
  normalizedRel = input.normalizedText && input.normalizedText.trim() ? `${stem}.normalized.md` : null;
  // attempts는 ★실패 시에만★ 증가(아래 catch) — 동기 경로와 동일 의미(재시도 횟수). 여기선 상태/단계만.
  job = await prisma.ingestJob.update({
    where: { id: existing.id },
    data: { status: "RUNNING", model: ingestModel, phase: "분석" },
  });
  // 이번 분석의 추출 메타를 source에 반영(동기 경로의 source.create가 하던 일과 동치).
  await prisma.source.update({
    where: { id: source.id },
