      normalizedPath: normalizedRel ?? source.normalizedPath, // 새 사이드카 없으면 기존 보존
    },
  });
} else {
  // ── 동기 경로(기존) — ★변경 없음★ ──
  // dedup: 같은 scope에 동일 원본이 ★실제로 LLM 분석되어 적용(APPLIED)★된 적 있으면 건너뛴다.
  //   ★단 '원본 그대로'(gate=RAW_IMPORT)만 적용된 자료는 아직 ‘분석’ 전이다★ → [AI로 분석] 재인제스트를 허용해야
  //   한다(RAW_IMPORT를 '분석됨'으로 치면 SKIPPED_DUP로 빠져 LLM 호출이 통째로 건너뛰어진다). 실패/미완료도 정리 후 재시도.
  const dup = await prisma.source.findUnique({
    where: { teamScope_sha256: { teamScope: scope, sha256: sha } },
    include: { ingestJobs: { where: { status: "APPLIED", NOT: { gate: "RAW_IMPORT" } }, take: 1 } },
  });
