  const present = new Set(extractShas(content));
  const missing = requiredShas.filter((s) => s && !present.has(s));
  if (!missing.length) return false;
  const add = missing.map((s) => `- sha256:${s}`).join("\n");
  if (/(^|\n)##\s*출처[^\n]*\n/.test(content)) {
    content = content.replace(/((^|\n)##\s*출처[^\n]*\n)/, `$1${add}\n`); // 기존 헤더 바로 뒤에 끼움
  } else {
    content = content.replace(/\s*$/, "") + `\n\n## 출처\n${add}\n`; // 섹션 없으면 파일 끝에 생성
  }
  await atomicWriteFile(abs, content); // 원자적(읽기 파드 보호)
  return true;
}

