//   임계는 ★관리자 UI 설정 우선★(없으면 env INGEST_T_REVIEW·기본 0.5).
const T_REVIEW = await getIngestReviewThreshold();
// ★결정적 모순 검증 게이트(B)★ — 분석 모델의 needs_human 자기보고는 강한 모델도 자주 놓쳐(관찰됨),
//   ‘자동적용 후보’일 때 ★분리된 전용 검증 패스★로 기존 위키와의 사실 충돌을 코드가 직접 확인한다.
