if (contradictionCheckEnabled() && !data.needs_human && (data.confidence ?? 1) >= T_REVIEW && !input.signal?.aborted) {
  try {
    let existingForCheck = heavyCtx?.pages ?? (await loadPages(scope));
    // 검사 대상 incoming = 분석 편집(개체·개념). ★augment(원문그대로→분석)★는 모순되는 단정이 ★보존 topic 본문★에
    //   있고 edits에선 빠져(보존), 그대로면 충돌이 게이트를 통과한다 → 그 topic 본문을 incoming에 더해 기존 위키와
