    let editsForCheck = data.edits ?? [];
    if (input.augment && input.preservePath) {
      try {
        const topicContent = await fs.readFile(wikiAbsPath(input.preservePath), "utf8");
        editsForCheck = [...editsForCheck, { op: "create", path: input.preservePath, content: topicContent }];
        existingForCheck = existingForCheck.filter((pg) => pg.path !== input.preservePath);
      } catch { /* 보존 topic 없음 → edits만 검사 */ }
    }
    // ★검사는 강한 모델로 고정★(분석이 약한 모델로 폴백해도) + ★활성 모델만★ — detectContradictions 공유.
