1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { allowedScopes, scopeWikiPrefix, canManageScope } from "@/lib/acl/scope";
4	import { prisma } from "@/lib/db";
5	import { getStaleDays } from "@/lib/settings";
6	import { flaggedPagesFromDownvotes } from "@/lib/wiki/feedbackFlags";
7	import { scopeIdFromTeamScope } from "@/lib/jobs/stale";
8	
9	// 검토 큐 — 인제스트가 needs_human(모순/대체)으로 보류한 항목 목록. docs/12.
10	export const runtime = "nodejs";
11	
12	export async function GET() {
13	  const user = await getSessionUser();
14	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
15	
16	  // scope id(common·project-<slug>·personal/<id>) → ★한글 표시명★. 룸은 이름 조회(메모이즈).
17	  const nameCache = new Map<string, string>();
18	  async function scopeName(scope: string): Promise<string> {
19	    if (nameCache.has(scope)) return nameCache.get(scope)!;
20	    let name = scope;
21	    if (scope === "common") name = "회사 공통";
22	    else if (scope.startsWith("personal/")) name = "개인 위키";
23	    else if (scope.startsWith("project-")) {
24	      const p = await prisma.project.findUnique({ where: { slug: scope.slice("project-".length) }, select: { name: true } });
25	      name = p?.name ?? scope;
26	    }
27	    nameCache.set(scope, name);
28	    return name;
29	  }
30	
31	  const allowed = [...new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)))];
32	  const jobs = await prisma.ingestJob.findMany({
33	    where: { status: "NEEDS_REVIEW", teamScope: { in: allowed } },
34	    include: { source: { select: { id: true, title: true, type: true } } },
35	    orderBy: { id: "desc" },
36	    take: 50,
37	  });
38	
39	  const items = await Promise.all(jobs.map(async (j) => {
40	    let summary = "";
