import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix, canManageScope } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { getStaleDays } from "@/lib/settings";
import { flaggedPagesFromDownvotes } from "@/lib/wiki/feedbackFlags";
import { scopeIdFromTeamScope } from "@/lib/jobs/stale";

// 검토 큐 — 인제스트가 needs_human(모순/대체)으로 보류한 항목 목록. docs/12.
export const runtime = "nodejs";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });

  // scope id(common·project-<slug>·personal/<id>) → ★한글 표시명★. 룸은 이름 조회(메모이즈).
  const nameCache = new Map<string, string>();
  async function scopeName(scope: string): Promise<string> {
    if (nameCache.has(scope)) return nameCache.get(scope)!;
    let name = scope;
    if (scope === "common") name = "회사 공통";
    else if (scope.startsWith("personal/")) name = "개인 위키";
    else if (scope.startsWith("project-")) {
      const p = await prisma.project.findUnique({ where: { slug: scope.slice("project-".length) }, select: { name: true } });
      name = p?.name ?? scope;
    }
    nameCache.set(scope, name);
    return name;
  }

  const allowed = [...new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)))];
  const jobs = await prisma.ingestJob.findMany({
    where: { status: "NEEDS_REVIEW", teamScope: { in: allowed } },
    include: { source: { select: { id: true, title: true, type: true } } },
    orderBy: { id: "desc" },
    take: 50,
  });

  const items = await Promise.all(jobs.map(async (j) => {
    let summary = "";
    let edits: { op: string; path: string }[] = [];
    let contradictions: { subject: string; existing: string; incoming: string; page?: string; existingDate?: string }[] = [];
    try {
      const es = JSON.parse(j.editSet || "{}");
      summary = es.log_entry || "";
      edits = (es.edits || []).map((e: { op: string; path: string }) => ({ op: e.op, path: e.path }));
      if (Array.isArray(es.contradictions)) contradictions = es.contradictions;
    } catch { /* 파싱 실패 무시 */ }
    // ★최근성(언제 자료인지)★ — 충돌하는 기존 페이지의 마지막 갱신 시각을 붙여, reviewer가 '최신=새 자료'를 한눈에 판단.
    const cPaths = contradictions.map((c) => c.page).filter((p): p is string => !!p);
    if (cPaths.length) {
      const docs = await prisma.wikiDoc.findMany({ where: { path: { in: cPaths } }, select: { path: true, updatedAt: true } });
      const dateByPath = new Map(docs.map((d) => [d.path, d.updatedAt.toISOString()]));
      contradictions = contradictions.map((c) => (c.page && dateByPath.has(c.page) ? { ...c, existingDate: dateByPath.get(c.page) } : c));
    }
    return {
      jobId: j.id,
      scope: j.teamScope,
      scopeName: await scopeName(j.teamScope), // 한글 룸 이름
      sourceId: j.source.id,
      sourceTitle: j.source.title,
      sourceType: j.source.type,
      confidence: j.confidence,
      createdAt: j.createdAt.toISOString(),
      summary,
      edits,
      contradictions, // ★모순 검증 게이트(B)★ — 왜 검토인지(기존↔새 자료 충돌). 없으면 빈 배열.
    };
  }));

  // 승격 요청 — ★대상 범위(toScope)를 관리할 수 있는 사람★에게 노출(부모 룸 OWNER·공통은 ADMIN).
  const allPending = await prisma.promotion.findMany({ where: { status: "PENDING" }, orderBy: { id: "desc" }, take: 50 });
  const promotions: { id: number; fromScope: string; toScope: string; fromName: string; toName: string; path: string; title: string; createdAt: string }[] = [];
  for (const p of allPending) {
    if (await canManageScope(user, p.toScope)) {
      promotions.push({ id: p.id, fromScope: p.fromScope, toScope: p.toScope, fromName: await scopeName(p.fromScope), toName: await scopeName(p.toScope), path: p.path, title: p.title, createdAt: p.createdAt.toISOString() });
    }
  }

  // ★관리 권한 scope★(오래됨·👎 환류 공통) — 한 번만 계산해 둘이 재사용.
  const manageable: string[] = [];
  for (const s of allowed) if (await canManageScope(user, s)) manageable.push(s);
  const inManageable = (p: string) => manageable.some((s) => p === s || p.startsWith(s + "/"));

  // 스테일(오래된) 페이지 — 관리 권한 scope에서 임계일보다 오래 갱신 안 된 지식 페이지. 검토·갱신 권장.
  const staleDays = await getStaleDays();
  const stalePages: { path: string; scope: string; scopeName: string; title: string; ageDays: number; link: string }[] = [];
  if (staleDays > 0 && manageable.length) {
    const cutoff = new Date(Date.now() - staleDays * 86400 * 1000);
    const docs = await prisma.wikiDoc.findMany({
      where: { scope: { in: manageable }, updatedAt: { lt: cutoff }, category: { in: ["entities", "concepts", "topics"] } },
      orderBy: { updatedAt: "asc" }, take: 80,
      select: { path: true, scope: true, title: true, updatedAt: true },
    });
    // ★'열면 자동 갱신'(WikiReview) 반영★ — 최근 열람/검토된 페이지는 제외(stale 잡과 동일 기준).
    const reviews = docs.length ? await prisma.wikiReview.findMany({ where: { path: { in: docs.map((d) => d.path) } }, select: { path: true, reviewedAt: true } }) : [];
    const reviewedAt = new Map(reviews.map((r) => [r.path, r.reviewedAt]));
    for (const d of docs) {
      const rv = reviewedAt.get(d.path);
      if (rv && rv >= cutoff) continue; // 최근 열람/검토됨 → 방치 아님
      const fresh = rv && rv > d.updatedAt ? rv : d.updatedAt;
      stalePages.push({
        path: d.path, scope: d.scope, scopeName: await scopeName(d.scope), title: d.title,
        ageDays: Math.floor((Date.now() - fresh.getTime()) / 86400000),
        link: `/?room=${encodeURIComponent(scopeIdFromTeamScope(d.scope))}&page=${encodeURIComponent(d.path)}`,
      });
      if (stalePages.length >= 30) break;
    }
  }

  // ★👎 많이 받은 페이지(A-3)★ — 관리 권한 scope의 부정평가를 인용 페이지별로 모아 '검토 1순위'로.
  //   ACL 이중 가드: 피드백 scope ∈ 관리가능 + 페이지 경로 ∈ 관리가능(cross-scope 인용된 타 scope 페이지 제외).
  const flaggedPages: { path: string; scope: string; scopeName: string; title: string; downvotes: number }[] = [];
  if (manageable.length) {
    const downs = await prisma.answerFeedback.findMany({
      where: { rating: "down", scope: { in: manageable } },
      orderBy: { createdAt: "desc" }, take: 500,
      select: { queryLogId: true },
    });
    const qids = [...new Set(downs.map((d) => d.queryLogId))];
    if (qids.length) {
      const qls = await prisma.queryLog.findMany({ where: { id: { in: qids } }, select: { id: true, citedPaths: true } });
      const citedById = new Map<number, string[]>();
      for (const q of qls) { try { const j = JSON.parse(q.citedPaths || "[]"); if (Array.isArray(j)) citedById.set(q.id, j as string[]); } catch { /* noop */ } }
      const downAnswers = downs.map((d) => ({ citedPaths: citedById.get(d.queryLogId) ?? [] }));
      const flagged = flaggedPagesFromDownvotes(downAnswers, { allow: inManageable, minCount: 1, limit: 20 });
      if (flagged.length) {
        const docs = await prisma.wikiDoc.findMany({ where: { path: { in: flagged.map((f) => f.path) } }, select: { path: true, scope: true, title: true } });
        const byPath = new Map(docs.map((d) => [d.path, d]));
        for (const f of flagged) {
          const d = byPath.get(f.path);
          flaggedPages.push({
            path: f.path, scope: d?.scope ?? "", scopeName: d ? await scopeName(d.scope) : "",
            title: d?.title ?? (f.path.split("/").pop()?.replace(/\.md$/, "") ?? f.path),
            downvotes: f.downvotes,
          });
        }
      }
    }
  }

  return NextResponse.json({ items, promotions, stalePages, flaggedPages, staleDays, isAdmin: user.role === "ADMIN" });
}

