import { describe, it, expect, vi } from "vitest";
import {
  salientTokens, existingPagesAtRisk, buildContradictionPrompt,
  normalizeContradictionResult, findContradictions, pickStrongCheckModel, pagesToSupersede,
} from "../lib/contradict";

const isStrong = (p: string) => ["anthropic", "gemini", "codex", "claude-cli", "openai"].includes(p);
import type { WikiPage } from "../lib/wiki/context";
import type { WikiEdit } from "../lib/wiki/applyEditSet";

// 결정적 모순 검증 게이트(B) — 순수 사전필터·프롬프트·정규화 + 주입식 LLM 오케스트레이션.
// 시나리오 기반: "킹스커피 제일 잘 팔리는 메뉴 = 아이스아메리카노"(기존) ↔ "= 페퍼민트"(새 자료).

const page = (path: string, content: string): WikiPage => ({ path, content });
const edit = (path: string, content: string, op: "create" | "append" = "create"): WikiEdit => ({ op, path, content });

describe("salientTokens", () => {
  it("길이≥2 토큰만, 영문 소문자화", () => {
    const t = salientTokens("킹스커피 a Nimbus 메뉴 7");
    expect(t.has("킹스커피")).toBe(true);
    expect(t.has("nimbus")).toBe(true);
    expect(t.has("메뉴")).toBe(true);
    expect(t.has("a")).toBe(false); // 1글자 제외
  });
});

describe("existingPagesAtRisk (비용 사전필터)", () => {
  const existing = [
    page("common/topics/카페-메뉴.md", "킹스커피에서 제일 잘 팔리는 메뉴는 아이스아메리카노다."),
    page("common/entities/widgetron.md", "위젯트론은 IoT 회사다. 매출 100억."),
  ];

  it("제목이 달라도 고유명사(킹스커피, 길이≥4) 공유로 위험 페이지를 잡는다", () => {
    const edits = [edit("common/topics/카페.md", "킹스커피에서 제일 잘 팔리는 메뉴는 페퍼민트다.")];
    const at = existingPagesAtRisk(existing, edits);
    expect(at.map((p) => p.path)).toContain("common/topics/카페-메뉴.md");
    expect(at.map((p) => p.path)).not.toContain("common/entities/widgetron.md");
  });

