// ── 승인 중 멈춘(APPLYING) 잡 회수 판정 (순수) ───────────────────────────────────
// 검토 승인은 NEEDS_REVIEW→APPLYING로 원자적 클레임 후 적용·커밋한다(app/api/review/[jobId]).
//   정상 에러는 그 라우트가 NEEDS_REVIEW로 롤백하지만, 클레임 직후 ★프로세스가 하드 크래시★(OOM·파드 kill)
//   하면 APPLYING으로 박제돼 재승인이 막힌다(클레임은 NEEDS_REVIEW만 허용). → updatedAt이 임계보다 오래된
//   APPLYING는 '멈춘 것'으로 보고 NEEDS_REVIEW로 되돌린다(자가치유). 임계가 넉넉해(기본 10분) 정상 승인
//   (락 안에서 수초)을 회수하지 않으므로 이중적용 위험이 없다. DB 실행은 lib/ingest.reapStuckApplying.
//   BUG-TRIAGE #9. 비활성: INGEST_APPLYING_REAP_MS=0.

/** APPLYING 회수 임계(ms). 0이면 회수 비활성. 기본 10분. */
export const APPLYING_REAP_MS = Number(process.env.INGEST_APPLYING_REAP_MS ?? 10 * 60 * 1000);

/** 이 시각 이전에 마지막 갱신된 APPLYING는 멈춘 것 — updateMany의 updatedAt 컷오프(순수). */
export function applyingReapCutoff(nowMs: number, thresholdMs: number = APPLYING_REAP_MS): Date {
  return new Date(nowMs - thresholdMs);
}

/** 잡 하나가 '멈춘 APPLYING'인지(순수). thresholdMs<=0이면 항상 false(비활성). */
export function isStuckApplying(
  status: string,
  updatedAtMs: number,
  nowMs: number,
  thresholdMs: number = APPLYING_REAP_MS,
): boolean {
  if (thresholdMs <= 0) return false;
  return status === "APPLYING" && nowMs - updatedAtMs >= thresholdMs;
}

