// ★멈춘 APPLYING 잡 회수★ (BUG-TRIAGE #9) — 클레임 직후 하드 크래시로 APPLYING에 박제된 검토건을
//   updatedAt 임계 경과 시 NEEDS_REVIEW로 되돌린다(자가치유·멱등). 검토 목록 조회 시 호출 → 다시 목록에 뜸.
//   임계가 넉넉해(기본 10분) 정상 승인(락 안 수초)은 회수하지 않는다. 비활성: INGEST_APPLYING_REAP_MS=0.
//   순수 컷오프 판정은 lib/jobs/reap(테스트됨).
export async function reapStuckApplying(scopes?: string[]): Promise<number> {
  if (APPLYING_REAP_MS <= 0) return 0;
  const cutoff = applyingReapCutoff(Date.now());
  const r = scopes && scopes.length
    ? await prisma.ingestJob.updateMany({ where: { status: "APPLYING", updatedAt: { lt: cutoff }, teamScope: { in: scopes } }, data: { status: "NEEDS_REVIEW" } })
    : await prisma.ingestJob.updateMany({ where: { status: "APPLYING", updatedAt: { lt: cutoff } }, data: { status: "NEEDS_REVIEW" } });
  return r.count;
}

