import { describe, it, expect, afterEach, vi } from "vitest";
import { isStuckApplying, applyingReapCutoff } from "../lib/jobs/reap";
import { contradictionFailClosed, checkFailedContradiction } from "../lib/contradict";

// BUG-TRIAGE #9(APPLYING reaper) · #1(모순 검사 fail-closed 정책) 회귀 테스트.

describe("isStuckApplying (BUG-TRIAGE #9)", () => {
  const now = 1_000_000_000_000;
  const min = 60_000;

  it("APPLYING이고 임계(10분) 넘게 갱신 없으면 멈춘 것으로 본다", () => {
    expect(isStuckApplying("APPLYING", now - 11 * min, now, 10 * min)).toBe(true);
  });

  it("APPLYING이라도 임계 이내면 멈춘 게 아니다(정상 승인 회수 금지)", () => {
    expect(isStuckApplying("APPLYING", now - 5 * min, now, 10 * min)).toBe(false);
  });

  it("APPLYING이 아니면 항상 false", () => {
    expect(isStuckApplying("NEEDS_REVIEW", now - 60 * min, now, 10 * min)).toBe(false);
    expect(isStuckApplying("APPLIED", now - 60 * min, now, 10 * min)).toBe(false);
  });

  it("임계<=0이면 비활성(절대 회수 안 함)", () => {
    expect(isStuckApplying("APPLYING", 0, now, 0)).toBe(false);
  });

  it("컷오프는 now-threshold 시각", () => {
    expect(applyingReapCutoff(now, 10 * min).getTime()).toBe(now - 10 * min);
  });
});

describe("contradiction fail-closed 정책 (BUG-TRIAGE #1)", () => {
  afterEach(() => { vi.unstubAllEnvs(); });

  it("기본은 fail-open(false) — 기존 동작 불변", () => {
    vi.stubEnv("INGEST_CONTRADICTION_FAILCLOSED", "");
    expect(contradictionFailClosed()).toBe(false);
  });

  it("INGEST_CONTRADICTION_FAILCLOSED=true면 fail-closed", () => {
    vi.stubEnv("INGEST_CONTRADICTION_FAILCLOSED", "true");
    expect(contradictionFailClosed()).toBe(true);
  });

  it("검사 불능 사유 항목은 subject·existing·incoming을 모두 채운다(검토 콘솔 표시용)", () => {
    const c = checkFailedContradiction();
    expect(c.subject).toBeTruthy();
    expect(c.existing).toBeTruthy();
    expect(c.incoming).toBeTruthy();
  });
});

