import { test, expect } from "@playwright/test";

// 페이지 딥링크(?room=&page=, 알림이 쓰는 것)로 위키 페이지 열기 → 본문 + 관련 페이지(노이즈 수정 검증: 칩 수 상한).
test.describe("위키", () => {
  test("딥링크로 페이지 열림 + 관련 페이지 상한", async ({ page }) => {
    await page.goto("/?room=common&page=common%2Fconcepts%2Fcovid19-prevention.md");
    // 위키 탭이 활성화되고 본문(코로나19)이 보여야 함.
    await expect(page.locator(".wk-tab.active")).toContainText("위키", { timeout: 20_000 });
    await expect(page.getByText(/코로나/).first()).toBeVisible({ timeout: 20_000 });
    // 관련 페이지가 뜨면 칩 수가 상한(이웃 + 유사 ≤ 12) 이내 — '너무 많이 뜨던' 문제 회귀 가드.
    const rel = page.locator(".wt-related").first();
    if (await rel.count()) {
      const chips = rel.locator("a, button");
      expect(await chips.count()).toBeLessThanOrEqual(12);
    }
  });
});

"use client";

import { confirmDialog } from "@/components/ui/Dialog";
import { toUserMessage } from "./errMsg";
import Avatar from "./Avatar";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import {
  IconUpload, IconFileText, IconCircleCheck, IconAlertTriangle, IconClockHour4,
  IconChevronRight, IconTrash, IconCalendar, IconExternalLink, IconArrowUpRight, IconArticle,
  IconArrowsExchange, IconArchive, IconArrowBackUp, IconTrashX, IconSparkles, IconInfoCircle, IconRefresh, IconCopy, IconX,
} from "@tabler/icons-react";
import { typeIcon, typeLabel } from "./fileIcons";
import ModelSelect, { ModelDot, ModelBadges, type ModelOpt } from "./ModelSelect";
import { copyToClipboard } from "./clipboard";
import { kstStamp, kstDateStr, kstTimeStr } from "@/lib/time";
import { isRecent, RECENT_DAYS } from "@/lib/recency";
import { isTranscribedExtractor } from "@/lib/transcript";
import { summarizeBatch, batchSummaryText, groupStagedByModel } from "@/lib/uploadBatch";
import { chunkedUpload, chunkedUploadEnabled } from "./chunkedUpload";
import { useDismissedNew } from "./useDismissedNew";

// 실패 사유가 ★출력 길이 초과(자료가 너무 커서 AI 정리가 잘림)★인지 — 이 경우 '원본 그대로 추가'를 권장한다.
const isTooLargeErr = (e?: string | null) => !!e && /(최대 길이|maxOutputTokens|max_tokens|잘렸|너무 큽니다)/i.test(e);

// 클립보드 복사 버튼(복사됨 피드백). 실패 사유 전문 복사 등에 사용.
function CopyButton({ text, label = "복사" }: { text: string; label?: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" className="mat-rowbtn" style={{ alignSelf: "flex-start" }}
      onClick={async () => { if (await copyToClipboard(text)) { setDone(true); setTimeout(() => setDone(false), 1500); } }}>
      <IconCopy size={12} />{done ? "복사됨" : label}
    </button>
  );
}

// 모델 id를 사람이 읽기 좋은 짧은 라벨로(예: claude-cli/sonnet → "Claude sonnet (구독)"). 없으면 id 그대로.
function modelLabel(id?: string | null): string {
  if (!id) return "";
  if (id.startsWith("claude-cli/")) return `Claude ${id.split("/")[1]} (구독)`;
  if (id === "codex") return "Codex";
  if (id.startsWith("claude")) return "Claude API";
  return id; // gemini-2.5-flash 등은 id 그대로 (정보성 충분)
}

// 사용량만큼 ★종량 과금★되는 공급자(API 결제) — 경고 뱃지·확인 팝업용. 구독(codex/claude-cli)·무료(gemini/groq)·로컬 제외.
const isPaidProvider = (p?: string) => p === "openai" || p === "anthropic";

// 경과 시간 mm:ss 표기 (분석 진행 중·완료·실패 시간 표시용).
function fmtElapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

// 원본 파일 용량 표시(B/KB/MB/GB) — 10단위 미만은 소수 1자리로 가독성.
function fmtBytes(n?: number | null): string {
  if (n == null || n < 0) return "";
  if (n < 1024) return `${n} B`;
  const u = ["KB", "MB", "GB", "TB"]; let v = n / 1024, i = 0;
  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
  return `${v < 10 ? v.toFixed(1) : Math.round(v)} ${u[i]}`;
}

function SourceGroup({ ym, items, onArchive, onWiki, onRecover, onAnalyze, onFileRaw, onCancel, onRestore, onPurge, deleting, acting, canceling, now, notes, durations, canManage, archivedMode, defaultOpen, seenNew, onSeen }: {
  ym: string; items: SourceItem[]; onArchive: (s: SourceItem) => void; onWiki: (s: SourceItem) => void;
  onRecover: (s: SourceItem) => void; onAnalyze: (s: SourceItem, reanalyze?: boolean) => void;
  onFileRaw: (s: SourceItem) => void; onCancel: (s: SourceItem) => void;
  onRestore?: (s: SourceItem) => void; onPurge?: (s: SourceItem) => void;
  deleting: number | null; acting: Map<number, { label: string; at: number; ctrl: AbortController }>; canceling?: Set<number>; now: number; notes: Record<number, string>; durations: Map<number, number>; canManage: boolean; archivedMode?: boolean; defaultOpen?: boolean;
  seenNew: (id: string) => boolean; onSeen: (s: SourceItem) => void; // 'N(최근)' 마크 — 클릭 시 제거
}) {
  const [open, setOpen] = useState(defaultOpen ?? false);
  return (
    <div>
      <button className="mat-group" onClick={() => setOpen((o) => !o)}>
        <IconChevronRight size={13} className={`tree-caret${open ? " open" : ""}`} />
        <IconCalendar size={14} />{ym}<span className="mat-group-count">({items.length})</span>
      </button>
      {open && items.map((s) => {
        const FIcon = typeIcon(s.type);
        // '잔여'(재처리 복구) = ★텍스트 없는 중단 PENDING·FAILED만★. 전사·추출이 끝난(hasText) PENDING은
        //   분석 대기 상태이므로 [AI로 분석]을 띄운다(음성 전사만 하고 분석 전인데 '재처리'가 뜨던 문제 수정).
        const stuck = (s.status === "PENDING" && !s.hasText) || s.status === "FAILED";
        const isRaw = s.status === "APPLIED" && s.gate === "RAW_IMPORT"; // '원본 그대로' 보관 — 아직 분석 안 됨
        // [AI로 분석] 대상: 원본 그대로 보관본 + 미분석 보존본 + ★전사·추출만 되고 분석 전(PENDING+hasText)★.
        const canAnalyze = !archivedMode && (isRaw || s.status === "UNANALYZED" || (s.status === "PENDING" && s.hasText));
        // [다시 분석] 대상: 이미 분석된 자료(원본 보존하며 엔티티·개념 갱신).
        const canReanalyze = !archivedMode && s.status === "APPLIED" && !isRaw;
        const act = acting.get(s.id);
        const busy = !!act;
        const serverProc = !busy && (s.status === "RUNNING" || s.status === "APPLYING" || s.status === "QUEUED"); // 다른 세션·비동기 큐 등 서버측 처리 중
        const isCanceling = !!canceling && canceling.has(s.id) && (busy || serverProc); // 취소 누른 직후~서버가 취소 확정(상태 전환)하기 전까지
        // 처리 중 모델 + 경과 시간 — 로컬(이 클라가 누름) 시작시각 우선, 없으면 ★서버 잡 시작시각(startedAt)★.
        //   → 비동기 큐·새로고침·다른 세션이 시작한 작업도 경과가 1초마다 증가(이전엔 클라 시작분만 카운트).
        const procLabel = busy ? act.label : (serverProc ? modelLabel(s.model) : "");
        // 서버 경과는 QUEUED·RUNNING(비동기 인제스트)만 — APPLYING(검토승인)은 잡 createdAt이 오래돼 경과가 틀림.
        const startMs = busy ? act.at : (serverProc && (s.status === "QUEUED" || s.status === "RUNNING") && s.startedAt ? Date.parse(s.startedAt) : 0);
        const elapsed = (busy || serverProc) && startMs ? fmtElapsed(now - startMs) : "";
        // 처리 배지 문구: 단계(phase)와 경과를 함께. QUEUED는 phase(대기 중/요약 k/N), 그 외는 '처리 중 {모델} · {phase}'.
        const procText = isCanceling ? "취소 중…" : (() => {
          const label = s.status === "QUEUED" ? (s.phase || "대기 중") : `처리 중${procLabel ? ` ${procLabel}` : ""}${s.phase ? ` · ${s.phase}` : ""}`;
          return elapsed ? `${label} · ${elapsed}` : label;
        })();
        const note = notes[s.id];
        return (
          <div key={s.id} className="mat-item-row" style={{ paddingLeft: 16 }} onClick={() => onSeen(s)}>
            <div className="mat-item tree">
              <FIcon size={17} className="mat-ficon" />
              <div className="mat-item-main">
                <div className="mat-item-title" title={s.title}>{s.title}</div>
                <div className="mat-item-sub"><span className="mat-ext">{typeLabel(s.type)}</span> · <span title={kstStamp(new Date(s.createdAt))}>{kstTimeStr(new Date(s.createdAt))}</span>
                  {s.byteSize != null && <> · <span title={s.extractor && (s.extractor.startsWith("groq-") || s.extractor.startsWith("gemini-")) ? "원본 음성·영상 용량" : "원본 파일 용량"}>{fmtBytes(s.byteSize)}</span></>}
                  {isRecent(s.createdAt) && !seenNew(`mat:${s.id}`) && <span className="new-badge" title={`최근 ${RECENT_DAYS}일 이내 추가됨 (클릭하면 사라짐)`}>N</span>}
                  {s.uploader
                    ? <> · <span className="mat-uploader" title={s.anonymous ? "익명 요청 자료 — 관리자에게만 실명 표시(감사)" : "업로더"}>
                        <Avatar className="mat-uploader-av" initials={s.uploader.avatar.initials} color={s.uploader.avatar.color} imageUrl={s.uploader.avatar.imageUrl} />
                        {s.uploader.name}{s.anonymous ? " 🔒" : ""}</span></>
                    : s.anonymous ? <> · <span className="mat-uploader anon" title="익명 기여자 (작성자는 감사 기록에 유지됨)">익명 기여자</span></> : null}
                  {/* ★처리 중엔 '처리 중 {모델}', 완료 후엔 '분석 {모델}'★ — 어떤 모델이 도는지/분석했는지. */}
                  {busy || serverProc ? (
                    <span className="mat-model-badge proc" title={isCanceling ? "취소 중" : "처리 중"}>{procText}</span>
                  ) : s.model && ((s.status === "APPLIED" && !isRaw) || s.status === "NEEDS_REVIEW") ? (
                    <span className="mat-model-badge" title="이 자료를 분석한 모델">분석 {modelLabel(s.model)}{s.durationMs != null ? ` · ${fmtElapsed(s.durationMs)}` : durations.has(s.id) ? ` · ${fmtElapsed(durations.get(s.id)!)}` : ""}</span>
                  ) : null}
                  {/* ★음성·영상 전사 출처★ — Gemini 전사는 외부 학습 경고(민감 자료 주의), Groq는 외부 전송(미학습). 분석 모델과 별개. */}
                  {s.extractor?.startsWith("gemini-") ? (
                    <span className="mat-model-badge warn" title="이 자료는 Gemini로 음성을 텍스트로 변환함 — 오디오가 Google로 전송·학습됩니다. 민감 자료엔 쓰지 마세요.">Gemini 텍스트 변환 · 외부학습</span>
                  ) : s.extractor?.startsWith("groq-") ? (
                    <span className="mat-model-badge" title="이 자료는 Groq Whisper로 음성을 텍스트로 변환함(외부 전송, 학습엔 미사용)">Groq 텍스트 변환</span>
                  ) : null}
                  {/* ★스캔 PDF 처리★ — 페이지를 이미지에서 전사(OCR)했고, 모델 한도에 맞춰 해상도를 낮췄음(다운스케일)을 명시. 원본 보존 — 품질 저하 투명성. */}
                  {s.extractor?.startsWith("pdf-scan") && (
                    <span className="mat-model-badge" title="스캔 PDF라 각 페이지를 이미지에서 전사(OCR)했습니다. 모델 한도에 맞춰 페이지 해상도를 낮춰(다운스케일) 전사했으며, ★원본 파일은 그대로 보존★됩니다(필요하면 더 높은 해상도로 다시 분석 가능).">스캔 전사 · 다운스케일</span>
                  )}
                </div>
                {note && <div className="mat-item-note">{note}</div>}
              </div>
              {!archivedMode && (
                <span className={`mat-status ${s.status === "APPLIED" ? (isRaw ? "muted" : "ok") : s.status === "FAILED" ? "err" : s.status === "UNANALYZED" ? "warn" : s.status === "PENDING" || s.status === "RUNNING" || s.status === "APPLYING" || s.status === "QUEUED" ? "pend" : "muted"}`}>
                  {isCanceling ? "취소 중…" : busy ? "처리 중…" : s.status === "APPLIED" ? (isRaw ? "원본 보관" : "반영됨") : s.status === "FAILED" ? "실패" : s.status === "SKIPPED_DUP" ? "중복" : s.status === "UNANALYZED" ? "미분석" : s.status === "QUEUED" ? "대기 중" : s.status === "PENDING" ? "분석 대기" : s.status === "RUNNING" ? "분석 중…" : s.status === "APPLYING" ? "반영 중…" : s.status === "NEEDS_REVIEW" ? "검토 대기" : s.status ?? "-"}
                </span>
              )}
              {/* 액션은 ★아이콘만★(고정폭) — 상태 배지·아이콘 열 정렬 유지. '재처리'·'AI로 분석'은 아래 별도 줄로 뺀다. */}
              <div className="mat-acts">
                {/* L4: 원본 정리됨이면 열기 비활성(지식·추출본은 유지). */}
                {s.rawEvicted
                  ? <span className="mat-act" style={{ opacity: 0.4, cursor: "default" }} title="원본은 보존정책에 따라 정리됨(분석본·위키 지식은 유지)"><IconExternalLink size={13} /></span>
                  : <a className="mat-act" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기"><IconExternalLink size={13} /></a>}
                {archivedMode ? (
                  <>
                    <button className="mat-act" disabled={busy} onClick={() => onRestore!(s)} title="복원"><IconArrowBackUp size={14} /></button>
                    <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onPurge!(s)} title="영구삭제"><IconTrashX size={14} /></button>
                  </>
                ) : (
                  <>
                    {/* A-ⓕ: 분석이 콘텐츠 페이지를 0개 만든 경우(resultPages===0) '페이지로' 링크 숨김(가짜 404 방지). null=구버전/RAW→현행 유지. */}
                    {!stuck && s.resultPages !== 0 && <button className="mat-act" onClick={() => onWiki(s)} title="위키 페이지로 이동"><IconArrowUpRight size={13} /></button>}
                    {s.hasExtracted && (
                      <a className="mat-act" href={`/api/materials/${s.id}/extracted`} target="_blank" rel="noreferrer" title="추출본(읽은 텍스트)"><IconArticle size={13} /></a>
                    )}
                    {canManage && <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onArchive(s)} title="아카이브(삭제)"><IconTrash size={13} /></button>}
                  </>
                )}
              </div>
            </div>
            {/* 별도 줄: 잔여 재처리 / AI로 분석(눈에 띄는 라벨 버튼) — 행 정렬에 영향 없음 */}
            {!archivedMode && stuck && !busy && (
              <button className="mat-rowbtn" onClick={() => onRecover(s)} title="이 자료를 (위쪽에서 고른 방식으로) 다시 처리">재처리</button>
            )}
            {!archivedMode && !busy && canAnalyze && (
              <button className="mat-rowbtn analyze" onClick={() => onAnalyze(s)}
                title="AI로 분석해 엔티티·개념으로 정리합니다">
                <IconSparkles size={13} />AI로 분석
              </button>
            )}
            {!archivedMode && !busy && canReanalyze && (
              <button className="mat-rowbtn" onClick={() => onAnalyze(s, true)}
                title="이미 분석된 자료를 최신 방식으로 다시 분석 (원본 보존, 엔티티·개념 갱신)">
                <IconRefresh size={13} />다시 분석
              </button>
            )}
            {/* 처리 중: '분석 중' 버튼(툴팁 유지·비활성)과 취소를 ★나란히★(취소가 '분석 중'을 대체하지 않게). 경과 시간은 위 배지에. */}
            {!archivedMode && busy && (
              <div className="mat-busy-row">
                <button className={`mat-rowbtn ${canReanalyze ? "" : "analyze"}`} disabled
                  title={canReanalyze ? "이미 분석된 자료를 최신 방식으로 다시 분석 (원본 보존, 엔티티·개념 갱신)" : "AI로 분석해 엔티티·개념으로 정리합니다"}>
                  {canReanalyze ? <IconRefresh size={13} /> : <IconSparkles size={13} />}분석 중…
                </button>
                <button className="mat-rowbtn cancel" onClick={() => onCancel(s)} title="분석 취소 (서버 작업도 중단)">
                  <IconX size={13} />취소
                </button>
              </div>
            )}
            {/* 실패 사유 — 전문 표시 + 복사. (오래 걸려 실패한 PDF 등의 원인 진단·공유용) */}
            {!archivedMode && s.status === "FAILED" && s.error && (
              <div className="mat-failbox">
                <div className="mat-failbox-head">
                  <span style={{ flex: 1, minWidth: 0, fontSize: 11.5, fontWeight: 600, color: "var(--color-text-danger)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>「{s.title}」 실패{s.model ? ` · 모델 ${modelLabel(s.model)}` : ""}</span>
                  <CopyButton text={s.error} label="사유 복사" />
                </div>
                <pre style={{ margin: 0, maxHeight: 160, overflow: "auto", whiteSpace: "pre-wrap", wordBreak: "break-word", fontSize: 11.5, lineHeight: 1.5, fontFamily: "var(--font-mono, monospace)", color: "var(--color-text-secondary)", userSelect: "text" }}>{s.error}</pre>
                {/* 출력 길이 초과(자료가 너무 큼)면 → 토큰 0인 '원본 그대로 추가'를 권장 + 바로 실행 */}
                {isTooLargeErr(s.error) && s.hasText && (
                  <div style={{ marginTop: 8, fontSize: 11.5, color: "var(--color-text-secondary)", lineHeight: 1.5 }}>
                    💡 자료가 커서 AI 정리 결과가 한 번에 안 담깁니다. 원문을 그대로 보존하는 <b>원본 그대로 추가</b>(토큰 0)를 권장합니다. 더 잘게 나눠 올려 분석할 수도 있어요.
                    <div style={{ marginTop: 6 }}>
                      <button className="mat-rowbtn analyze" disabled={busy} onClick={() => onFileRaw(s)}>
                        <IconFileText size={13} />원본 그대로 추가
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface SourceItem { id: number; title: string; type: string; createdAt: string; status: string | null; confidence: number | null; gate: string | null; phase?: string | null; progress?: number | null; resultPages?: number | null; startedAt?: string | null; durationMs?: number | null; byteSize?: number | null; extractStatus?: string | null; extractor?: string | null; hasExtracted?: boolean; hasText?: boolean; looksOrganized?: boolean; archived?: boolean; rawEvicted?: boolean; error?: string | null; model?: string | null; recoModel?: string | null; anonymous?: boolean; uploader?: { name: string; avatar: { initials: string; color: string; imageUrl: string | null } } | null }
interface UploadPolicy { provider: string; tier?: string; textOnly: boolean; vision?: boolean; exts: string[]; accept: string; note: string }
interface AnalyzeModel { model: string; provider: string; label: string; reason: string }
// 스테이징(보관됨)된 한 파일/입력 — 사용자가 [처리 시작]을 누르기 전까지 대기.
interface Reco { model: string; provider: string; label: string; reason: string }
interface Staged { key: number; sourceId: number | null; name: string; hasText: boolean; status: "staging" | "staged" | "running" | "done" | "error" | "skip"; note?: string; reco?: Reco; at?: number; ctrl?: AbortController }

const extOf = (n: string) => n.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";

// 새로고침 복원 시 ★아직 서버로 안 보낸 대기 항목만★ 남긴다(sourceId 있고 status==="staged").
//   'running'은 서버가 이미 처리 중이거나 처리한 것(결과는 '최근 자료'에 RUNNING/반영됨으로 보임)이라
//   ★대기에 되살리지 않는다★(같은 파일이 분석 중인데 대기에도 뜨는 중복 방지). 업로드 중('staging')·
//   완료/실패(done/skip/error)도 버린다(결과·재처리는 '최근 자료'에서).
function normalizeStaged(arr: Staged[]): Staged[] {
  return (Array.isArray(arr) ? arr : [])
    .filter((s) => s && s.sourceId && s.status === "staged")
    .map((s) => ({ ...s, note: undefined, at: undefined, ctrl: undefined }));
}

// 업로드 원본을 ★일자(YYYY-MM-DD)★로 묶어 최신순 트리로. 항목은 하위로 들여쓰고 시각(초)만 표시.
function groupByDay(sources: SourceItem[]): [string, SourceItem[]][] {
  const m = new Map<string, SourceItem[]>();
  for (const s of sources) {
    const k = kstDateStr(new Date(s.createdAt)); // ★한국 시간(KST) 일자★로 묶음
    const arr = m.get(k);
    if (arr) arr.push(s); else m.set(k, [s]);
  }
  return [...m.entries()].sort((a, b) => b[0].localeCompare(a[0]));
}

// ★월(상위) → 일(하위)★ 2단계. 둘 다 최신순. 월 큰 묶음 아래에 일자별로 나눠 보기 쉽게.
function groupByMonthThenDay(sources: SourceItem[]): [string, [string, SourceItem[]][]][] {
  const m = new Map<string, [string, SourceItem[]][]>();
  for (const [day, items] of groupByDay(sources)) {       // 이미 일자 최신순
    const month = day.slice(0, 7);
    const arr = m.get(month);
    if (arr) arr.push([day, items]); else m.set(month, [[day, items]]);
  }
  return [...m.entries()].sort((a, b) => b[0].localeCompare(a[0]));
}

// 상위 '월' 묶음 — 펼치면 그 아래 일자 그룹(SourceGroup)들을 한 칸 들여써 보여준다.
function MonthGroup({ month, count, children, defaultOpen }: { month: string; count: number; children: ReactNode; defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen ?? false);
  return (
    <div className="mat-month">
      <button className="mat-group" onClick={() => setOpen((o) => !o)}>
        <IconChevronRight size={13} className={`tree-caret${open ? " open" : ""}`} />
        <IconCalendar size={14} />{month}<span className="mat-group-count">({count})</span>
      </button>
      {open && <div style={{ paddingLeft: 14 }}>{children}</div>}
    </div>
  );
}

// ★L2 비동기 큐 적재 시 보여주는 임시 안내★ — 단일 진실(설정·정리 양쪽이 같은 문자열을 쓰게 상수화).
//   QUEUED 동안만 의미 있고, 폴링이 상태를 QUEUED 밖으로 갱신하면 제거한다(아래 정리 effect).
const QUEUED_NOTE = "분석 예약됨 · 백그라운드에서 처리 중";

export default function MaterialsTab({ scope, hidden, onOpenWiki, modelsRev, dataRev, onDataChanged }: {
  scope: string; hidden?: boolean; onOpenWiki: (path: string) => void; modelsRev?: number; dataRev?: number; onDataChanged?: () => void;
}) {
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  // ★룸(scope)별 처리중 상태★ — '분석 중…'·입력 잠금이 그 처리를 시작한 룸에서만 보이게(다른 룸으로 새지 않음, ChatTab streamingScopes와 동일 패턴).
  const [busyScopes, setBusyScopes] = useState<Set<string>>(new Set());
  const busy = busyScopes.has(scope); // [처리 시작] 진행 중(현재 룸 기준)
  const setBusyFor = (sc: string, on: boolean) => setBusyScopes((s) => { const n = new Set(s); if (on) n.add(sc); else n.delete(sc); return n; });
  const [err, setErr] = useState<string | null>(null);
  const [uploadMode, setUploadMode] = useState<"llm" | "raw">("llm"); // 처리 방식(확정 시 적용)
  const [staged, setStaged] = useState<Staged[]>([]); // 대기(스테이징)된 항목
  const [sources, setSources] = useState<SourceItem[]>([]);
  const [anonUpload, setAnonUpload] = useState(false); // 익명으로 업로드(표시만 숨김, uploadedBy는 감사용 유지)
  const [diarize, setDiarize] = useState(false); // 음성·영상 화자 구분(Gemini 전용·외부학습) — STT에만 적용
  const [geminiAudioOptIn, setGeminiAudioOptIn] = useState(false); // G: ffmpeg 없는 서버에서 큰 음성을 Gemini로 전사 허용(기본 꺼짐=안전)
  // (회의록 처리 토글은 제거 — 전사 소스는 서버가 ★무조건 회의록으로★ 처리)
  const [diarizeSwitched, setDiarizeSwitched] = useState(false); // 화자 구분이 분석 모델을 Gemini로 자동 전환했나(말풍선 표시)
  const preDiarizeRef = useRef<{ model: string; picked: boolean } | null>(null); // 화자 구분 끄면 되돌릴 직전 모델
  const [deleting, setDeleting] = useState<number | null>(null);
  const [delNote, setDelNote] = useState<string | null>(null);
  const [canManage, setCanManage] = useState(false); // 아카이브·영구삭제 권한(룸 관리자)
  const [archivedSources, setArchivedSources] = useState<SourceItem[]>([]);
  const [showArchived, setShowArchived] = useState(false);
  const [convertExts, setConvertExts] = useState<string[]>([]);
  const [policy, setPolicy] = useState<UploadPolicy | null>(null);
  const [analyzeModel, setAnalyzeModel] = useState<AnalyzeModel | null>(null); // 서버 추천(기본값·사유 툴팁용)
  const [analyzeModels, setAnalyzeModels] = useState<ModelOpt[]>([]);          // 고를 수 있는 분석 모델 목록
  const [analyzeModelId, setAnalyzeModelId] = useState<string>("");            // 적용할 분석 모델(자동추천 또는 사용자 선택)
  const [modelUserPicked, setModelUserPicked] = useState(false);              // 사용자가 셀렉트박스로 직접 바꿨나(=자동추천 끔)
  const [groupOverrides, setGroupOverrides] = useState<Record<string, string>>({}); // H: 추천 모델 그룹별 오버라이드(reco모델 id → 고른 모델 id)
  const [pickFor, setPickFor] = useState<{ s: SourceItem; reanalyze: boolean; recover?: boolean } | null>(null); // AI로 분석/다시 분석/재처리 모델 선택 팝업 대상
  const [pickDiarize, setPickDiarize] = useState(false); // 재분석 팝업: 음성 소스의 화자 구분 선택(Gemini)
  const { has: seenNew, dismiss: dismissNew } = useDismissedNew(); // 'N(최근)' 마크 — 자료 항목 클릭 시 제거
  const [pickId, setPickId] = useState<string>("");                            // 팝업에서 고른 모델
  const [dragOver, setDragOver] = useState(false);
  const [acting, setActing] = useState<Map<number, { label: string; at: number; ctrl: AbortController }>>(new Map()); // 처리 중 소스 id → {모델 라벨, 시작 시각, 취소 컨트롤러}
  const [canceling, setCanceling] = useState<Set<number>>(new Set()); // 취소 누른 소스 id — 즉시 '취소 중…' 표시(서버가 상태 전환하면 폴링이 해제)
  const [durations, setDurations] = useState<Map<number, number>>(new Map()); // 분석 끝난 소스 id → ★최종 소요(ms)★ — 완료 후에도 배지에 남겨 표시
  const markDuration = (id: number, ms: number) => setDurations((d) => new Map(d).set(id, ms));
  // 새 분석을 시작할 때 그 소스의 ★옛 클라 측정 소요값을 지운다★ — 안 지우면 이전 분석의 소요(또는 ≈0)가
  //   배지에 남아 새 분석의 서버 실측(durationMs)을 가린다(완료 후 0:00 → 새로고침하면 정상값으로 바뀌던 버그).
  const clearDuration = (id: number) => setDurations((d) => { if (!d.has(id)) return d; const c = new Map(d); c.delete(id); return c; });
  const [notes, setNotes] = useState<Record<number, string>>({}); // 처리 결과 메모(자동전환·반영 등)
  const fileRef = useRef<HTMLInputElement>(null);
  // 분석 경과 시간 — 처리 중(acting)일 때 1초마다 now를 갱신해 배지의 경과 시간이 흐르게 한다.
  const [now, setNow] = useState(0);
  const stagingRunning = staged.some((s) => s.status === "running"); // 대기열 처리 중에도 경과 시간 tick
  // 서버측 처리 중(비동기 큐·다른 세션·새로고침 후) — 경과 타이머(A)가 이때도 흘러야 한다.
  const anyServerProc = sources.some((s) => s.status === "RUNNING" || s.status === "APPLYING" || s.status === "QUEUED");
  useEffect(() => {
    // ★서버 작업도 포함★ — 빠지면 now가 갱신 안 돼(초기 0) 서버 경과가 0:00에 박제된다.
    if (acting.size === 0 && !stagingRunning && !anyServerProc) return;
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, [acting.size, stagingRunning, anyServerProc]);
  // 대기 큐 영속화(sessionStorage) — ★scope별 저장소★. AppShell이 새로고침 후 scope를 비동기로 복원해도
  // 해당 scope의 큐를 정확히 되살리려면 모든 scope의 큐를 ref 맵에 들고 있어야 한다(chat·위키탭과 동일 패턴).
  const stagedStore = useRef<Record<string, Staged[]>>({});
  const stagedRef = useRef(staged); stagedRef.current = staged;
  const matPrevScope = useRef(scope);
  const matFirstSave = useRef(true); // 첫(빈) 저장은 건너뛰어 복원본을 덮어쓰지 않음
  const matRestored = useRef(false); // mount 복원 완료 전엔 빈 staged를 store에 저장하지 않음

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) {
        setSources(d.sources); setConvertExts(d.convertExts || []); setPolicy(d.policy || null);
        setCanManage(Boolean(d.canManage)); setAnalyzeModel(d.analyzeModel || null);
      }
    } catch { /* noop */ }
  }, [scope]);

  // ★서버측 처리 중(RUNNING/APPLYING) 항목이 있으면 자동 폴링★ — 취소·완료가 수동 새로고침 없이 반영되게.
  //   (취소=abort는 즉시 보내지만 서버가 상태를 '취소됨'으로 바꾸는 덴 시간차가 있어, 폴링으로 따라잡는다.)
  //   anyServerProc는 위(경과 타이머)에서 정의 — 같은 값 재사용.
  useEffect(() => {
    if (!anyServerProc) return;
    const t = setInterval(() => { void load(); }, 2000);
    return () => clearInterval(t);
  }, [anyServerProc, load]);
  // ★서버측 처리(비동기 큐 등)가 끝나는 순간 위키 탭 등에 갱신 신호★ — 분석이 백그라운드에서 끝나면
  //   (anyServerProc true→false 전이) 새 엔티티/개념 페이지가 위키 탭에 ★새로고침 없이★ 바로 보이게 한다.
  //   (동기 경로는 analyzeItem/runStaged가 직접 onDataChanged를 부르고, 이건 폴링으로만 끝을 아는 비동기 완료를 커버.)
  const prevServerProc = useRef(false);
  useEffect(() => {
    if (prevServerProc.current && !anyServerProc) onDataChanged?.();
    prevServerProc.current = anyServerProc;
  }, [anyServerProc, onDataChanged]);
  // 서버 상태가 더 이상 처리중이 아니면 '취소 중' 표시 해제(취소 확정 → 실패/완료 박스로 전환).
  useEffect(() => {
    setCanceling((c) => {
      if (c.size === 0) return c;
      const next = new Set([...c].filter((id) => { const s = sources.find((x) => x.id === id); return !!s && (s.status === "RUNNING" || s.status === "APPLYING"); }));
      return next.size === c.size ? c : next;
    });
  }, [sources]);
  // ★비동기 큐 완료 시 '분석 예약됨' 임시 안내 제거★ — 폴링이 상태를 QUEUED 밖(분석 중/반영됨/검토대기 등)으로
  //   갱신하면 그 안내는 obsolete다. 배지는 '반영됨'인데 note에 '예약됨 · 처리 중'이 남던 버그 수정.
  //   ★QUEUED_NOTE 한 종류만★ 정리(실패·성공·취소 등 다른 note는 보존).
  useEffect(() => {
    setNotes((n) => {
      let changed = false; const c = { ...n };
      for (const s of sources) if (c[s.id] === QUEUED_NOTE && s.status !== "QUEUED") { delete c[s.id]; changed = true; }
      return changed ? c : n;
    });
  }, [sources]);

  // 고를 수 있는 분석 모델 목록(질의와 동일 라인업). 관리자가 모델을 토글하면(modelsRev) 다시 읽는다.
  useEffect(() => {
    fetch("/api/models", { cache: "no-store" }).then((r) => r.json()).then((d) => {
      setAnalyzeModels(d.models || []);
    }).catch(() => { /* noop */ });
  }, [modelsRev]);
  // ★자료를 판단해 분석 모델 자동 추천★ — 무겁/복잡한 게 있으면 구독 고품질(claude-cli·codex), 아니면 기본(Gemini).
  //   서버가 업로드 응답에 reco(추천 모델+사유)를 실어 주고, 그중 구독 고품질 추천이 하나라도 있으면 그걸 택한다.
  const enabledHas = (id: string) => analyzeModels.some((m) => m.id === id && m.enabled);
  const stagedRecos = staged.map((s) => s.reco).filter((r): r is Reco => !!r);
  const effReco: Reco | null =
    stagedRecos.find((r) => r.provider === "claude-cli" && enabledHas(r.model)) // 무거운 자료 → Claude 구독 우선
    ?? stagedRecos.find((r) => r.provider === "codex" && enabledHas("codex"))   // 또는 codex
    ?? stagedRecos.find((r) => enabledHas(r.model))                             // 그 외 자료 추천
    ?? (analyzeModel && enabledHas(analyzeModel.model) ? analyzeModel : null); // 스테이징 전 = 서버 기본 추천
  const recommendedId = effReco && enabledHas(effReco.model) ? effReco.model : (analyzeModels.find((m) => m.enabled)?.id || "");
  // 추천을 셀렉트박스에 자동 반영(자료 올리면 그에 맞게 바뀜).
  //  ★관리자가 모델을 끄면★ 현재 선택이 비활성이 될 수 있으므로 — 사용자가 직접 골랐어도(modelUserPicked)
  //   그 선택이 더는 활성이 아니면 ★활성 추천으로 교정★한다(비활성 모델이 선택된 채 남지 않게).
  useEffect(() => {
    const curEnabled = !!analyzeModelId && enabledHas(analyzeModelId);
    if (modelUserPicked && curEnabled) return; // 사용자가 고른 ★활성★ 모델은 유지
    if (recommendedId && recommendedId !== analyzeModelId) setAnalyzeModelId(recommendedId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [recommendedId, modelUserPicked, analyzeModelId, analyzeModels]);

  // 아카이브된 자료 목록(복원/영구삭제 뷰) — 별도 조회(?archived=1).
  const loadArchived = useCallback(async () => {
    try {
      const res = await fetch(`/api/materials?scope=${encodeURIComponent(scope)}&archived=1`, { cache: "no-store" });
      const d = await res.json();
      if (res.ok) setArchivedSources(d.sources || []);
    } catch { /* noop */ }
  }, [scope]);

  // scope 전환: 이전 룸 큐를 store에 저장 + 새 룸 큐를 store에서 복원(없으면 빈 큐). 목록·메모는 초기화.
  useEffect(() => {
    const prev = matPrevScope.current;
    if (prev !== scope) {
      if (matRestored.current) stagedStore.current[prev] = stagedRef.current; // 복원 완료 후에만 이전 큐 저장
      matPrevScope.current = scope;
    }
    setSources([]); setErr(null); setDelNote(null); setArchivedSources([]); setShowArchived(false); setModelUserPicked(false); setGroupOverrides({});
    // ★룸 전환 시 업로드 토글 초기화★ — 회의록·화자구분·자동전환·익명이 다른 룸으로 새지 않게(버그 수정).
    setDiarize(false); setDiarizeSwitched(false); preDiarizeRef.current = null; setAnonUpload(false); setGeminiAudioOptIn(false);
    setStaged(normalizeStaged(stagedStore.current[scope] || []));
    load();
  }, [scope, load]);

  // ★마운트 복원★ — 저장된 모드 + scope별 큐 맵을 ref로 적재하고 현재 scope 큐 복원.
  //   (scope 효과 뒤 선언 → 마운트 시 scope 효과의 빈 큐를 덮어쓴다. store는 ref라 동기 적재되어
  //    이후 AppShell이 scope를 바꿔도 scope 효과가 그 scope의 큐를 정확히 복원한다.)
  useEffect(() => {
    try {
      const raw = sessionStorage.getItem("llmwiki_materials_v1");
      if (raw) {
        const d = JSON.parse(raw);
        if (d.mode === "llm" || d.mode === "raw") setUploadMode(d.mode);
        if (d.staged && typeof d.staged === "object") stagedStore.current = d.staged;
      }
    } catch { /* noop */ }
    matRestored.current = true;
    setStaged(normalizeStaged(stagedStore.current[scope] || []));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // 영속화 — 현재 scope 큐를 store에 반영 후 SS 저장(첫 빈 저장은 건너뜀). scope는 클로저 최신값.
  useEffect(() => {
    if (matFirstSave.current) { matFirstSave.current = false; return; }
    stagedStore.current[scope] = staged;
    try { sessionStorage.setItem("llmwiki_materials_v1", JSON.stringify({ mode: uploadMode, staged: stagedStore.current })); } catch { /* noop */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [staged, uploadMode]);

  // ★대기↔최근자료 정합성★ — 대기 항목은 그 소스가 ★아직 살아있고 미처리(PENDING)★일 때만 유지한다.
  //   소스가 처리됐거나(RUNNING·반영됨·검토대기 등) ★삭제·교체돼 사라졌으면★(분석 시 dedup이 원본을 지우고
  //   새로 만들어 sourceId가 바뀜) 대기에서 제거 → '분석된 파일이 대기에 그대로 남는' 중복을 막는다.
  //   (소스 생성 직후 staging 중인 항목은 sourceId 없음 → 유지.)
  useEffect(() => {
    if (!sources.length) return;
    setStaged((prev) => {
      const next = prev.filter((s) => {
        if (!s.sourceId) return true; // 업로드(staging) 진행 중 — 유지
        const src = sources.find((x) => x.id === s.sourceId);
        return !!src && src.status === "PENDING"; // 살아있고 아직 미처리일 때만 대기 유지
      });
      return next.length === prev.length ? prev : next;
    });
  }, [sources]);

  // 교차 갱신: 위키 배너에서 [AI로 분석]하거나 다른 경로로 데이터가 바뀌면 목록 재조회(초기 마운트는 건너뜀).
  const firstRev = useRef(true);
  useEffect(() => {
    if (firstRev.current) { firstRev.current = false; return; }
    load(); if (showArchived) loadArchived();
  }, [dataRev]); // eslint-disable-line react-hooks/exhaustive-deps

  // ★자료 탭으로 (다시) 들어올 때 자동 새로고침★ — 다른 세션·경로로 바뀐 최근 자료/상태가 탭만 바꾸면 바로 보이게
  //   한다(WikiTab과 동일 패턴, 수동 새로고침 불필요). hidden true→false 전이에만 발동.
  const matPrevHidden = useRef(hidden);
  useEffect(() => {
    if (matPrevHidden.current && !hidden) { load(); if (showArchived) loadArchived(); }
    matPrevHidden.current = hidden;
  }, [hidden, load]); // eslint-disable-line react-hooks/exhaustive-deps

  async function openWiki(s: SourceItem) {
    try {
      const res = await fetch(`/api/materials/${s.id}/pages`);
      const d = await res.json();
      // ★자료 자체의 주제(topic) 페이지로 이동★ — 분석이 만든 개념/개체 중 첫 항목이 아니라, 그 자료를 정리한
      //   topics/ 페이지를 우선한다(없으면 첫 페이지로 폴백).
      const paths: string[] = d.paths ?? [];
      const target = paths.find((p) => /\/topics\//.test(p)) ?? paths[0];
      if (res.ok && target) onOpenWiki(target);
      else setDelNote(`「${s.title}」에서 생성된 위키 페이지를 찾지 못했습니다.`);
    } catch {
      setDelNote("위키 페이지를 찾지 못했습니다.");
    }
  }

  // 자료 아카이브(소프트 삭제) — 목록에서 숨기고 아카이브로. 원본·위키 페이지는 보존. 룸 관리자만.
  async function archiveSource(s: SourceItem) {
    if (!await confirmDialog(`원본 「${s.title}」을(를) 아카이브할까요?\n목록에서 숨겨지며, 아카이브에서 복원하거나 영구삭제할 수 있습니다. (위키 페이지는 그대로 유지됩니다)`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "archive" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "아카이브에 실패했습니다.");
      setDelNote(`「${s.title}」 아카이브됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${toUserMessage(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 아카이브에서 복원 — 다시 활성 목록으로.
  async function restoreSource(s: SourceItem) {
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "restore" }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "복원에 실패했습니다.");
      setDelNote(`「${s.title}」 복원됨`);
      await Promise.all([load(), loadArchived()]);
    } catch (e) {
      setDelNote(`오류: ${toUserMessage(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 영구삭제 — 원본·사이드카 제거 + 인용 위키 페이지에 '출처 소실' 표시. 되돌릴 수 없음.
  async function purgeSource(s: SourceItem) {
    if (!await confirmDialog(`원본 「${s.title}」을(를) 영구삭제할까요? 되돌릴 수 없습니다.\n매핑된 위키 페이지는 보존되며 '출처 소실' 표시가 남습니다.`)) return;
    setDeleting(s.id); setDelNote(null);
    try {
      const res = await fetch(`/api/materials/${s.id}`, { method: "DELETE" });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "삭제에 실패했습니다.");
      setDelNote(`「${s.title}」 영구삭제됨 · 위키 ${d.annotated}곳에 출처 소실 표시`);
      await Promise.all([load(), loadArchived()]);
      onDataChanged?.(); // 위키 페이지에 흔적 → 트리/리더 갱신
    } catch (e) {
      setDelNote(`오류: ${toUserMessage(e)}`);
    } finally {
      setDeleting(null);
    }
  }

  // 파일 선택/드롭 → ★스테이징만★(자동 처리 안 함). 사용자가 모드 고르고 [처리 시작]을 눌러야 인제스트.
  function onPickFile(e: React.ChangeEvent<HTMLInputElement>) {
    const files = e.target.files ? [...e.target.files] : [];
    e.target.value = "";
    if (files.length) void stageFiles(files);
  }
  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    const files = e.dataTransfer?.files ? [...e.dataTransfer.files] : [];
    if (files.length) void stageFiles(files);
  }

  // 스테이징 결과 해석: 중복/미분석은 더 처리할 수 없으니 'skip'(완료), 그 외는 'staged'(처리 대기).
  function toStaged(prev: Staged, data: { status?: string; sourceId?: number; hasText?: boolean; unanalyzed?: boolean; recommended?: Reco }): Staged {
    if (data.status === "SKIPPED_DUP") return { ...prev, status: "skip", note: "중복(건너뜀)", reco: data.recommended };
    if (data.unanalyzed || !data.sourceId) return { ...prev, status: "skip", note: "원본 보존(미분석)", reco: data.recommended };
    return { ...prev, status: "staged", sourceId: data.sourceId, hasText: !!data.hasText, reco: data.recommended };
  }

  // 파일을 스테이징(추출·보관만, 토큰 0). 허용 안 되는 확장자는 에러로 표시.
  async function stageFiles(files: File[]) {
    const allowExt = (n: string) => !policy || policy.exts.includes(extOf(n));
    const ok = files.filter((f) => allowExt(f.name));
    const blocked = files.filter((f) => !allowExt(f.name));
    setErr(null);
    const base = Date.now();
    setStaged((prev) => [
      ...prev,
      ...blocked.map((f, i) => ({ key: base + 9000 + i, sourceId: null, name: f.name, hasText: false, status: "error" as const, note: policy?.note || "지원하지 않는 형식" })),
      ...ok.map((f, i) => ({ key: base + i, sourceId: null, name: f.name, hasText: false, status: "staging" as const })),
    ]);
    const single = ok.length === 1 ? (title.trim() || undefined) : undefined;
    for (let i = 0; i < ok.length; i++) {
      const key = base + i;
      const f = ok[i];
      try {
        // ★diarize는 업로드가 아니라 [처리 시작](분석) 때 적용★ — 업로드 전사는 항상 Groq 평문(빠른 미리보기).
        // 모델 미전송 → 서버가 자동 모델 기준 게이팅.
        // ★청크/resumable(NEXT_PUBLIC_CHUNKED_UPLOAD)★ — 큰 파일을 청크로 나눠 ★실패 청크만 재시도★(GB급·불안정망).
        //   꺼져 있으면 아래 raw-body 스트리밍(현행). 둘 다 File(디스크 Blob)을 보내 클라 RAM 통적재 회피.
        if (f.size > 25 * 1024 * 1024 && chunkedUploadEnabled()) {
          const up = await chunkedUpload(f, { scope, title: single, anonymous: anonUpload, geminiOptIn: geminiAudioOptIn },
            (sent, total) => setStaged((p) => p.map((x) => (x.key === key ? { ...x, note: `올리는 중… ${Math.floor((sent / total) * 100)}%` } : x))));
          if (!up.ok) { setStaged((p) => p.map((x) => (x.key === key ? { ...x, status: "error", note: String(up.data.error || "업로드 실패") } : x))); continue; }
          setStaged((p) => p.map((x) => (x.key === key ? toStaged(x, up.data) : x)));
          continue;
        }
        let res: Response;
        if (f.size > 25 * 1024 * 1024) {
          // ★대용량(>25MB): raw-body 스트리밍★ — 서버가 RAM 통적재 없이 디스크로 흘려 받는다(§11.2).
          //   File(디스크 기반 Blob)을 body로 보내면 클라도 메모리 사본을 안 만든다. 메타는 쿼리스트링.
          const qs = new URLSearchParams({ scope, filename: f.name, mime: f.type || "" });
          if (single) qs.set("title", single);
          if (anonUpload) qs.set("anonymous", "true");
