// [처리 시작] — 대기(staged) 항목을 순차 처리(위키는 단일 라이터). 끝나면 목록·트리 갱신.
async function runStaged() {
  if (busy) return;
  const qScope = scope; // ★처리를 시작한 룸★ 고정(중간에 룸을 옮겨도 busy는 이 룸에만)
  const todo = staged.filter((s) => s.status === "staged" && s.sourceId);
  if (!todo.length) return;
  // ★유료(종량 과금) 경고★ — 선택/자동추천된 분석 모델 중 OpenAI·Claude API가 있으면 확인.
  if (uploadMode !== "raw") {
    const usesPaid = todo.some((it) => isPaidProvider(analyzeModels.find((m) => m.id === (modelForStaged(it) ?? it.reco?.model ?? analyzeModelId))?.provider));
    if (usesPaid && !await confirmDialog("선택/추천된 분석 모델 중 ★사용량만큼 과금★되는 유료 모델(OpenAI·Claude API)이 있습니다. 계속할까요?")) return;
  }
  setBusyFor(qScope, true); setErr(null);
  try {
    for (const it of todo) {
      // 표시 모델: 직접 고름이면 그 모델, 자동이면 ★서버가 고를 모델(업로드 시 reco)★.
      const procM = modelForStaged(it) ?? it.reco?.model ?? analyzeModelId; // H: 그룹 오버라이드 반영
      const ctrl = new AbortController(); // 항목별 취소(이 항목만 중단하고 다음 항목은 계속)
      const startedAt = Date.now();
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: "running", at: startedAt, ctrl, note: uploadMode === "raw" ? "추가 중…" : (procM ? `분석 중… · ${modelLabel(procM)}` : "분석 중…") } : x)));
      // ★최근 자료(sources) 행도 '처리 중'으로★ — 대기목록과 싱크(같은 자료가 한쪽 '분석중'·다른쪽 '분석 대기'로 어긋나던 문제).
      if (it.sourceId) setActing((a) => new Map(a).set(it.sourceId!, { label: procM ? modelLabel(procM) : "", at: startedAt, ctrl }));
      let r: { ok: boolean; note: string; queued?: boolean };
      try {
        r = await runProcess(it.sourceId!, it.hasText, ctrl.signal, modelForStaged(it)); // H: 그룹별 모델
      } catch (e) {
        const aborted = e instanceof Error && e.name === "AbortError";
        r = { ok: false, note: aborted ? "분석 취소됨" : `오류: ${toUserMessage(e)}` };
      }
      if (it.sourceId) { if (!r.queued) markDuration(it.sourceId, Date.now() - startedAt); setActing((a) => { const c = new Map(a); c.delete(it.sourceId!); return c; }); } // 소요 기록(★비동기 예약은 건너뜀=서버 durationMs가 표시★) + '처리 중' 해제
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: r.ok ? "done" : "error", at: undefined, ctrl: undefined, note: r.note } : x)));
      // ★각 항목이 끝나는 즉시★ 최근 자료·위키 갱신 — 전부 끝날 때까지 기다리지 않게(완료분이 바로 보임).
      await load();
      onDataChanged?.();
    }
  } finally {
    setBusyFor(qScope, false);
    await load();
    onDataChanged?.(); // 최종 갱신(위키 트리/리더)
  }
}

function clearStaged() { setStaged([]); setModelUserPicked(false); setGroupOverrides({}); } // 비우면 자동추천 재개
// 대기 항목 ★개별 삭제★ — 큐에서만 제거('비우기'와 동일 동작, 소스는 그대로). 처리 중 항목은 대신 취소 버튼.
function removeStaged(u: Staged) { setStaged((p) => p.filter((x) => x.key !== u.key)); }
// 진행 중 분석 취소 — (1) 클라 fetch abort(즉시) + (2) ★서버측 명시 취소★(배포 보강).
//   nginx 뒤에서 abort가 req.signal을 발화 못 해도 /cancel이 서버 in-flight 컨트롤러를 직접 abort해 중단을 전파한다.
function cancelItem(s: SourceItem) {
  acting.get(s.id)?.ctrl.abort();
  setCanceling((c) => new Set(c).add(s.id));
  fetch(`/api/materials/${s.id}/cancel`, { method: "POST" }).catch(() => { /* best-effort */ });
}

// 잔여(PENDING/FAILED) 복구 — 업로드 중 이탈 등으로 남은 항목을 현재 모드로 다시 처리.
async function recover(s: SourceItem, modelOverride?: string) {
  if (acting.has(s.id)) return;
  const lbl = (uploadMode === "raw" && s.hasText) ? "" : modelLabel(modelOverride || (modelUserPicked ? analyzeModelId : (s.recoModel ?? analyzeModelId))); // raw 복구는 모델 없음, 팝업/자동 모델
  const ctrl = new AbortController();
  const startedAt = Date.now();
  setActing((a) => new Map(a).set(s.id, { label: lbl, at: startedAt, ctrl }));
  setNotes((n) => { const c = { ...n }; delete c[s.id]; return c; });
  let queued = false; // ★비동기 예약이면 클라 측정(≈0)을 박제하지 않음 — 서버 durationMs가 실제 소요를 표시★
  try {
    const r = await runProcess(s.id, !!s.hasText, ctrl.signal, modelOverride, true); // ★재처리=음성이면 raw 재전사★
    queued = !!r.queued;
    setNotes((n) => ({ ...n, [s.id]: r.note }));
  } catch (e) {
    const aborted = e instanceof Error && e.name === "AbortError";
    setNotes((n) => ({ ...n, [s.id]: aborted ? "분석 취소됨" : `오류: ${toUserMessage(e)}` }));
  } finally {
    if (!queued) markDuration(s.id, Date.now() - startedAt);
    setActing((a) => { const c = new Map(a); c.delete(s.id); return c; });
    await load(); onDataChanged?.();
  }
}

// [AI로 분석]/[다시 분석] 클릭 → ★모델 선택 팝업★(추천 순 정렬·추천 뱃지·1순위/백업 같이). [분석]에서 실제 실행.
function openPick(s: SourceItem, reanalyze = false) {
  if (acting.has(s.id)) return;
  const reco = (s.recoModel && enabledHas(s.recoModel)) ? s.recoModel : recommendedId; // 항목 추천(없으면 기본 추천)
  setPickId(reco);
  setPickDiarize(false); // 재분석 화자 구분 선택 초기화(음성 소스에서만 노출)
  setPickFor({ s, reanalyze });
}
// ★재처리도 모델 선택 팝업★ — 분석이 필요한 항목만. raw 복구(텍스트 보존·모델 무관)는 팝업 없이 바로 실행.
function openRecoverPick(s: SourceItem) {
  if (acting.has(s.id)) return;
  if (uploadMode === "raw" && s.hasText) { void recover(s); return; }
  const reco = (s.recoModel && enabledHas(s.recoModel)) ? s.recoModel : recommendedId;
  setPickId(reco);
  setPickFor({ s, reanalyze: false, recover: true });

