            )}
          </button>
          {/* 다른 자료를 처리(분석/원본추가)하는 중엔 대기 비우기를 숨긴다 — 처리 중 실수 클릭으로 인한 혼동 방지.
              (분석은 서버에서 끝까지 돌므로 비워도 취소되진 않지만, UI 혼동을 막는다.) */}
          {staged.length > 0 && !busy && (
            <button className="mat-stage-clear" onClick={clearStaged}>대기 목록 비우기 ({staged.length})</button>
          )}
        </div>
      </div>

      <div className="mat-col mat-col-list">
        <div className="mat-card">
          <div className="mat-card-head"><IconFileText size={15} />최근 자료 {sources.length > 0 && `(${sources.length})`}</div>
          {delNote && <div className="mat-banner muted" style={{ marginBottom: 10 }}>{delNote}</div>}
          {sources.length === 0 ? (
            <p className="mat-desc">아직 올린 자료가 없습니다.</p>
          ) : (
            <div className="mat-tree">
              {groupByMonthThenDay(sources).map(([month, days], mi) => (
                <MonthGroup key={month} month={month} count={days.reduce((n, [, it]) => n + it.length, 0)} defaultOpen={mi === 0}>
                  {days.map(([ym, items], di) => (
                    <SourceGroup key={ym} ym={ym} items={items} defaultOpen={mi === 0 && di === 0} onArchive={archiveSource} onWiki={openWiki}
                      onRecover={openRecoverPick} onAnalyze={openPick} onFileRaw={fileAsRaw} onCancel={cancelItem}
                      deleting={deleting} acting={acting} canceling={canceling} now={now} notes={notes} durations={durations} canManage={canManage}
                      seenNew={seenNew} onSeen={(s) => dismissNew(`mat:${s.id}`)} />
                  ))}
                </MonthGroup>
              ))}
            </div>
          )}

          {/* 아카이브(소프트 삭제) 섹션 — 룸 관리자만. 펼칠 때 조회. */}
          {canManage && (
            <div className="mat-archive">
              <button className="mat-archive-head" onClick={() => { const n = !showArchived; setShowArchived(n); if (n) loadArchived(); }}>
                <IconChevronRight size={13} className={`tree-caret${showArchived ? " open" : ""}`} />
                <IconArchive size={14} />아카이브{archivedSources.length > 0 ? ` (${archivedSources.length})` : ""}
              </button>
              {showArchived && (
                archivedSources.length === 0 ? (
                  <p className="mat-desc mat-archive-empty">아카이브된 자료가 없습니다.</p>
                ) : (
                  <div className="mat-tree">
                    {groupByMonthThenDay(archivedSources).map(([month, days], mi) => (
                      <MonthGroup key={month} month={month} count={days.reduce((n, [, it]) => n + it.length, 0)} defaultOpen={mi === 0}>
                        {days.map(([ym, items], di) => (
                          <SourceGroup key={ym} ym={ym} items={items} defaultOpen={mi === 0 && di === 0} archivedMode canManage={canManage}
                            onArchive={archiveSource} onWiki={openWiki} onRecover={openRecoverPick} onAnalyze={openPick} onFileRaw={fileAsRaw} onCancel={cancelItem}
                            onRestore={restoreSource} onPurge={purgeSource}
                            deleting={deleting} acting={acting} now={now} notes={notes} durations={durations}
                            seenNew={seenNew} onSeen={(s) => dismissNew(`mat:${s.id}`)} />
                        ))}
                      </MonthGroup>
                    ))}
                  </div>
                )
              )}
            </div>
          )}
        </div>
      </div>

      {/* AI로 분석/다시 분석 — 모델 선택 팝업(추천 순 정렬·추천 뱃지·사용가능 1순위/백업 같이). */}
      {pickFor && (() => {
        const reco = (pickFor.s.recoModel && enabledHas(pickFor.s.recoModel)) ? pickFor.s.recoModel : recommendedId;
        // ★그룹(1순위+그 백업)을 통째로★ 정렬 — 추천이 속한 그룹만 최상단으로, 나머지·그룹 내부 순서는 원본 유지(안정 정렬).
        //   기존엔 추천만 위로 끌어올리고 모든 백업을 아래로 보내 ‘추천의 백업’이 추천과 떨어져 꼬였다.
        const groupOf = (m: ModelOpt) => (m.kind === "backup" ? (m.backupOf || m.id) : m.id);
        const recoM = analyzeModels.find((m) => m.id === reco);
        const recoGroup = recoM ? groupOf(recoM) : reco;
        const list = analyzeModels.filter((m) => m.enabled).slice()
          .sort((a, b) => (groupOf(a) === recoGroup ? 0 : 1) - (groupOf(b) === recoGroup ? 0 : 1));
        return (
          <div className="modal-overlay" onClick={() => setPickFor(null)}>
            <div className="set-modal-card" style={{ width: 460, maxWidth: "calc(100% - 32px)" }} onClick={(e) => e.stopPropagation()}>
              <div className="set-modal-head">
                <span className="set-modal-title">{pickFor.recover ? "재처리" : pickFor.reanalyze ? "다시 분석" : "AI로 분석"} · 모델 선택</span>
                <button className="modal-x" onClick={() => setPickFor(null)} aria-label="닫기"><IconX size={17} /></button>
              </div>
              <div style={{ padding: "12px 18px 16px" }}>
                <div className="mat-item-title" title={pickFor.s.title} style={{ marginBottom: 8 }}>「{pickFor.s.title}」</div>
                {/* ★음성·영상 = 전사+분석 2단계★ — 사용자는 어느 모델이 전사용인지 모를 수 있어 명시 + 추천(무료·미학습)을 강하게 어필. */}
                {isTranscribedExtractor(pickFor.s.extractor) && (
                  <div className="set-note" style={{ margin: "0 0 10px", lineHeight: 1.55 }}>
                    🎙 <b>음성·영상 자료는 2단계</b>예요 — <b>① 텍스트 변환</b>은 이미 끝났고(자동), 지금 고르는 건 <b>② 분석 모델</b>뿐입니다.<br />
                    전사된 텍스트 분석은 아래 <b style={{ color: "var(--color-accent)" }}>✓추천</b> 모델(무료·미학습)로 충분해요 — 외부학습 Gemini·유료 Claude를 굳이 고를 필요 없습니다.
                  </div>
                )}
                {list.length === 0 && <div className="set-note" style={{ margin: 0 }}>사용 가능한 모델이 없습니다(관리자 모델 관리·키 확인).</div>}
                <div style={{ display: "flex", flexDirection: "column", gap: 4, maxHeight: 320, overflowY: "auto" }}>
                  {list.map((m) => {
                    const nm = m.label.replace(/^↳ 백업 · /, "");
                    const isReco = m.id === reco;
                    const sel = m.id === pickId;
                    return (
                      <button key={m.id} type="button" onClick={() => setPickId(m.id)} className="model-admin-row"
                        style={{ textAlign: "left", cursor: "pointer", borderRadius: "var(--border-radius-md)", border: sel ? "1px solid var(--color-accent)" : "1px solid transparent", background: sel ? "color-mix(in srgb, var(--color-accent) 8%, transparent)" : "transparent" }}>
                        {/* 동그라미+정보를 좌측 그룹으로 묶음 — 행이 space-between이라 직접 두면 정보와 떨어짐 */}
                        <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
                          <ModelDot provider={m.provider} />
                          <div className="model-admin-info">
                            <span className="model-admin-name">{m.kind === "backup" ? "↳ " : ""}{nm}{isReco && <span style={{ marginLeft: 6, fontSize: 10.5, fontWeight: 600, color: "var(--color-accent)" }}>추천</span>}<ModelBadges provider={m.provider} /></span>
                            <span className="model-admin-meta">{m.kind === "backup" ? "백업" : "1순위"}</span>
                          </div>
                        </div>
                        {sel && <IconCircleCheck size={15} style={{ color: "var(--color-accent)" }} />}
                      </button>
                    );
                  })}
                </div>
                {pickFor.reanalyze && <div className="set-note" style={{ marginTop: 8 }}>원본은 그대로 두고 엔티티·개념 분석을 새로 만듭니다(토큰 사용).</div>}
                {/* ★음성·영상 재분석 시 화자 구분 선택★ — 처음엔 안 했어도 다시 분석에서 켤 수 있다(Gemini 필요). */}
                {isTranscribedExtractor(pickFor.s.extractor) && geminiAvailable && (
                  <label className="web-toggle" style={{ marginTop: 10 }} title="음성·영상에서 누가 말했는지 화자1/화자2로 구분 · Gemini로 텍스트 변환되어 외부 전송·학습됩니다(민감 자료엔 쓰지 마세요)">
                    <input type="checkbox" role="switch" aria-checked={pickDiarize} checked={pickDiarize} onChange={(e) => setPickDiarize(e.target.checked)} />
                    <span className={`web-toggle-label${pickDiarize ? " on" : ""}`}>화자 구분 (누가 말했는지 · Gemini) <span className="web-state">{pickDiarize ? "켜짐" : "꺼짐"}</span></span>
                  </label>
                )}
                <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 14 }}>
                  <button className="mat-rowbtn analyze" disabled={!pickId} onClick={async () => {
                    const f = pickFor;
                    const prov = analyzeModels.find((m) => m.id === pickId)?.provider;
                    if (isPaidProvider(prov) && !await confirmDialog("이 모델은 사용량만큼 과금됩니다(OpenAI·Claude API). 이 모델로 분석할까요?")) return;
                    setPickFor(null); if (f.recover) void recover(f.s, pickId); else void analyzeItem(f.s, f.reanalyze, pickId, pickDiarize);
                  }}>
                    <IconSparkles size={13} />{pickFor.recover ? "이 모델로 재처리" : "이 모델로 분석"}
                  </button>
                </div>
              </div>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

