import { test, expect } from "@playwright/test";

// 자료 업로드 → 처리 → 위키 반영 → 페이지 이동까지 ★일상 핵심 경로★를 UI로 검증한다.
//   ★토큰 0★: '원본 그대로 추가'(mode raw) 경로만 사용한다(LLM 호출 없음 — 비용 0, 결정적).
//   runStaged는 raw 모드에서 유료 확인 다이얼로그를 건너뛰므로(MaterialsTab) 헤드리스에서 막히지 않는다.
//   이 흐름은 자동화 공백(업로드 폼·[처리 시작]·상태 배지·자료↔위키 링크)을 덮어 "테스트 통과인데
//   실제로 다르게 동작"이 새던 구멍을 막는다. BUG-TRIAGE 다음 단계(b).

const PLACEHOLDER_TITLE = "제목 (단건 업로드/직접 입력 시, 비우면 자동)";
const PLACEHOLDER_TEXT = "여기에 내용을 붙여넣으세요…";

test.describe("자료 — 원본 그대로(토큰0) 풀 플로우", () => {
  test("붙여넣기 → 대기 추가 → 처리 시작 → 반영 → 위키 페이지 이동", async ({ page }) => {
    const tag = `E2E-raw-${Date.now()}`;
    const sentence = `${tag} 고유 본문입니다 — 원본 그대로 파일링 검증.`;

    await page.goto("/");
    // 1) 자료 탭
    await page.locator(".wk-tab", { hasText: "자료" }).click();
    await expect(page.locator(".wk-tab.active")).toContainText("자료");

    // 2) 처리 방식 = 원본 그대로(토큰 0)
    await page.locator(".mat-mode-btn", { hasText: "원본 그대로 추가" }).click();

    // 3) 제목 + 본문 입력 후 대기 목록에 추가
    await page.getByPlaceholder(PLACEHOLDER_TITLE).fill(tag);
    await page.getByPlaceholder(PLACEHOLDER_TEXT).fill(`# ${tag}\n${sentence}`);
    await page.locator(".mat-stage-add").click();

    // 4) 스테이징 완료 → [처리 시작] 활성(개수 표시). 서버 왕복이 있으니 넉넉히 대기.
    const submit = page.locator(".mat-submit");
    await expect(submit).toContainText("원본 그대로 추가 (", { timeout: 20_000 });
    await expect(submit).toBeEnabled();
    await submit.click();

    // 5) 최근 자료에 항목이 뜨고 '원본 보관' 상태가 된다(자료↔위키 정합).
    const listCol = page.locator(".mat-col-list");
    const row = listCol.locator(".mat-item-row", { hasText: tag });
    await expect(row).toBeVisible({ timeout: 30_000 });
    await expect(row.locator(".mat-status")).toContainText("원본 보관", { timeout: 30_000 });

    // 6) '위키 페이지로 이동' → 위키 탭으로 전환되고 본문이 보인다(BUG-TRIAGE #2/교훈#20: 링크 끊김 회귀 가드).
    await row.locator('[title="위키 페이지로 이동"]').click();
    await expect(page.locator(".wk-tab.active")).toContainText("위키", { timeout: 20_000 });
    await expect(page.getByText(tag).first()).toBeVisible({ timeout: 20_000 });
  });
});

